window.QUESTIONS = [{"id": "96-1-1", "round": 96, "session": 1, "number": 1, "text": "BlockedI/O와Non-BlockedI/O의차이점에 대하여 설명하시오 .", "sourcePage": 1, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-1-2", "round": 96, "session": 1, "number": 2, "text": "ACPI(AdvancedConfigurationandPowerInterface)에대하여설명하시오 .", "sourcePage": 1, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-1-3", "round": 96, "session": 1, "number": 3, "text": "I2C통신방식에 대하여 설명하시오 .", "sourcePage": 1, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-1-4", "round": 96, "session": 1, "number": 4, "text": "네트워크 전송에서 슬라이딩 윈도우 (SlidingWindow)알고리즘에 대하여 설명하시오 .", "sourcePage": 1, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-1-5", "round": 96, "session": 1, "number": 5, "text": "라우터 Backbone네트워크에 대하여 설명하시오 .", "sourcePage": 1, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-1-6", "round": 96, "session": 1, "number": 6, "text": "메모리 인터리빙 (MemoryInterleaving)의개념과활용방식에 대하여 설명하시오 .", "sourcePage": 1, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-1-7", "round": 96, "session": 1, "number": 7, "text": "슈퍼스칼라 ,VLIW(VeryLongInstructionWord),슈퍼파이프라인을비교하여 설명하시오 .", "sourcePage": 1, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-1-8", "round": 96, "session": 1, "number": 8, "text": "터보부스터와 오버클로킹을 비교하여 설명하시오 .", "sourcePage": 1, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-1-9", "round": 96, "session": 1, "number": 9, "text": "빅데이터 (BigData)처리 분석 기술인 하둡 (Hadoop)에대하여 설명하시오 .", "sourcePage": 1, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-1-10", "round": 96, "session": 1, "number": 10, "text": "데이터 마이닝 기술에서 연관규칙을 찾아주는 Apriori알고리즘을 예를 들어 설명하시오 .", "sourcePage": 1, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-1-11", "round": 96, "session": 1, "number": 11, "text": "클라우드 컴퓨팅의 멀티테넌시 (Multi-Tenancy)보안에대하여 설명하시오 .", "sourcePage": 1, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-1-12", "round": 96, "session": 1, "number": 12, "text": "윈도우 (Windows)운영체제의 부팅 순서를 단계별로 설명하시오 .", "sourcePage": 1, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-1-13", "round": 96, "session": 1, "number": 13, "text": "정보보안에서 저지통제 (DeterrentControl),탐지통제(DetectiveControl),교정통제 (CorrectiveControl),예방통제(PreventiveControl)를설명하시오.", "sourcePage": 1, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-2-1", "round": 96, "session": 2, "number": 1, "text": "AddressingMode의종류에 대하여 ADD명령 사례를 이용하여 설명하시오 .", "sourcePage": 2, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-2-2", "round": 96, "session": 2, "number": 2, "text": "멀티스래딩 (Multithreading)의개념과종류에 대하여 설명하고 ,Latency와Throughput 관점에서 장단점을 설명하시오 .", "sourcePage": 2, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-2-3", "round": 96, "session": 2, "number": 3, "text": "분산처리 시스템에서 MutualExclusion을구현하기 위한 TimeRing알고리즘과 TimeOrdering알고리즘의 동작을 설명하시오 .", "sourcePage": 2, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-2-4", "round": 96, "session": 2, "number": 4, "text": "데이터 압축기법인 런렝스 (RunLength)코딩과 허프만 (Huffman)코딩에 대하여 설명하시오 .", "sourcePage": 2, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-2-5", "round": 96, "session": 2, "number": 5, "text": "스마트폰 기반의 보안위협 및 대응책을 스마트폰 하드웨어 ,스마트폰 소프트웨어 , 네트워크 ,애플리케이션 마켓 등의 관점에서 설명하시오 .", "sourcePage": 2, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-2-6", "round": 96, "session": 2, "number": 6, "text": "소프트웨어 테스트 프로세스 성숙도 평가모델 TMMi(TestMaturityModelIntegration)와 시스템개발 프로세스 성숙도 평가모델 CMMi(CapacityMaturityModelIntegration)는 5레벨의 단계적 평가 프레임워크이다 .TMMi모델과 CMMi모델을 각각 설명하시오 .", "sourcePage": 2, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-3-1", "round": 96, "session": 3, "number": 1, "text": "캐시 (Cache)서버를 이용한 웹 서버의 부하 분산 방법에 대하여 설명하시오 .", "sourcePage": 3, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-3-2", "round": 96, "session": 3, "number": 2, "text": "하드웨어 인터럽트와 소프트웨어 인터럽트의 처리 흐름에 대하여 설명하시오 .", "sourcePage": 3, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-3-3", "round": 96, "session": 3, "number": 3, "text": "라우팅 프로토콜인 RIP(RoutingInformationProtocol),EGP(ExteriorGatewayProtocol), BPG(BorderGatewayProtocol)를비교하여 설명하시오 .", "sourcePage": 3, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-3-4", "round": 96, "session": 3, "number": 4, "text": "서로 다른 컴퓨터 시스템이나 단말기간의 통신 규약인 프로토콜이 가져야 하는 기능을 TCP(TransmissionControlProtocol)의사례를들어 설명하시오 .", "sourcePage": 3, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-3-5", "round": 96, "session": 3, "number": 5, "text": "웹 서비스가 네트워크 상에 있는 컴퓨터들 간에 상호운용이 가능한 것은 표준규격인 WSDL,SOAP,UDDI가 웹 서비스를 정의 , 등록 및 전송하게 해 주기 때문이다 .각 표준이 SOA를 구현하기 위하여 웹서비스로 등록하고 ,찾고 ,사용하는데 어떤 역할을 하는지 설명하시오 .", "sourcePage": 3, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-3-6", "round": 96, "session": 3, "number": 6, "text": "임베디드 시스템을 테스트하기 위한 하드웨어 및 소프트웨어 테스트 기법에 대하여 설명하시오 .", "sourcePage": 3, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-4-1", "round": 96, "session": 4, "number": 1, "text": "CPU가 명령을 수행하기 위한 파이프라이닝 (Pipelining)의개념과파이프라이닝을 방해 하는 위험 요소에 대하여 설명하시오 .", "sourcePage": 4, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-4-2", "round": 96, "session": 4, "number": 2, "text": "멀티코어 어플리케이션을 최적화하기 위한 프로그래밍과 컴파일러의 활용방법을 설명하시오 .", "sourcePage": 4, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-4-3", "round": 96, "session": 4, "number": 3, "text": "컴퓨터 아키텍처 관점에서 클라이 언 트/서버 ,분산 컴퓨팅 , 클라우드 컴퓨팅의 개념과 활용을 비교하여 설명하시오 .", "sourcePage": 4, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-4-4", "round": 96, "session": 4, "number": 4, "text": "네트워크 관리에서 DNS(DomainNameServer)의 관리정보와 기본 동작 내용에 대하여 설명하시오 .", "sourcePage": 4, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-4-5", "round": 96, "session": 4, "number": 5, "text": "가전제 품 이나 보안 시스템 등의 장치 들을 인터 넷 에 접속 하는 표준 방식인 OSGi(Open ServiceGatewayInitiative)프레임워크(Framework)의각레이어 (Layer)별기능(역할 )을 설명하시오 .", "sourcePage": 4, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "96-4-6", "round": 96, "session": 4, "number": 6, "text": "교통정보 서비스를 제공 하는 ITS(IntelligentTransportationSystem)에서정보수집, 정보처리 ,정보표 출 측면 의 구성 요소와 요소별 규모 산정방법을 설명하시오 .", "sourcePage": 4, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-1-1", "round": 98, "session": 1, "number": 1, "text": "멀티캐스트(Multicast)IP주소의특징을설명하시오.", "sourcePage": 5, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-1-2", "round": 98, "session": 1, "number": 2, "text": "안드로이드 응용프로그램 프레임워크에 대하여 설명하시오.", "sourcePage": 5, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-1-3", "round": 98, "session": 1, "number": 3, "text": "IEEE1471에대하여 설명하시오.", "sourcePage": 5, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-1-4", "round": 98, "session": 1, "number": 4, "text": "테스트 오라클에 대하여 설명하시오.", "sourcePage": 5, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-1-5", "round": 98, "session": 1, "number": 5, "text": "HTML5에대하여 설명하시오.", "sourcePage": 5, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-1-6", "round": 98, "session": 1, "number": 6, "text": "RTP(Real-timeTransportProtocol)의개념과특징에대하여설명하시오.", "sourcePage": 5, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-1-7", "round": 98, "session": 1, "number": 7, "text": "하이퍼바이저(Hypervisor)의두가지유형에 대하여 설명하시오.", "sourcePage": 5, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-1-8", "round": 98, "session": 1, "number": 8, "text": "운영체제(OS)에서의 상호배제(MutualExclusion)개념을설명하고이를 구현하는 방법을 하드웨어적 해결방안 및 소프트웨어적 해결방안으로 구분하여 설명하시오.", "sourcePage": 5, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-1-9", "round": 98, "session": 1, "number": 9, "text": "웹소켓(Websocket)에대하여설명하시오.", "sourcePage": 5, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-1-10", "round": 98, "session": 1, "number": 10, "text": "IEEE802.11네트워크에서의BSS(BasicServiceSet)에대하여설명하시오.", "sourcePage": 5, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-1-11", "round": 98, "session": 1, "number": 11, "text": "세마포어(Semaphore)와모니터(Monitor)의상호관계를설명하시오.", "sourcePage": 5, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-1-12", "round": 98, "session": 1, "number": 12, "text": "B-tree,B+-Tree를비교하여설명하시오.", "sourcePage": 5, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-1-13", "round": 98, "session": 1, "number": 13, "text": "운영체제(OS)에서의인터럽트(Interrupt)를정의하고그동작원리에대하여 설명하시오.", "sourcePage": 5, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-2-1", "round": 98, "session": 2, "number": 1, "text": "소프트웨어 개발 라이프사이클에 관한 나선형(Spiral)모델과애자일(Agile)방법에 대하여 유사점과 차이점을 중심으로 비교하여 설명하시오.", "sourcePage": 6, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-2-2", "round": 98, "session": 2, "number": 2, "text": "ISO/IEC14598-1에서정의한소프트웨어제품 평가(SoftwareProductEvaluation)에 대하여 설명하시오.", "sourcePage": 6, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-2-3", "round": 98, "session": 2, "number": 3, "text": "순서논리회로를 정의하고 이를 구성하는 여러 가지 플립플롭(Flip-Flop)의특징에 대하여 설명하시오.", "sourcePage": 6, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-2-4", "round": 98, "session": 2, "number": 4, "text": "P2P(Peer-to-Peer)네트워크의개념과장단점,이네트워크에서 제기되는 망중립성 (NetworkNeutrality)이슈에대하여설명하시오.", "sourcePage": 6, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-2-5", "round": 98, "session": 2, "number": 5, "text": "PHP(PersonalHomePage,HypertextPreprocessor)의개요와특징,개선점에대하여 설명하시오.", "sourcePage": 6, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-2-6", "round": 98, "session": 2, "number": 6, "text": "객체지향기법의 기본원칙을 기술하고 구조적 기법과 차별화되는 개념을 설명하시오.", "sourcePage": 6, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-3-1", "round": 98, "session": 3, "number": 1, "text": "임베디드 시스템(EmbeddedSystem)을특성별로분류하고신뢰성 향상을 위한 방안을 제시하시오.", "sourcePage": 7, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-3-2", "round": 98, "session": 3, "number": 2, "text": "정보시스템 감리의 프레임워크와 감리절차를 설명하시오.", "sourcePage": 7, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-3-3", "round": 98, "session": 3, "number": 3, "text": "운영체제(OS)에서수행되는 문맥교환(ContextSwitching)의개념과절차,문맥교환이 필요한 상황에 대하여 설명하시오.", "sourcePage": 7, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-3-4", "round": 98, "session": 3, "number": 4, "text": "중앙처리장치 캐쉬(CPUCache)의개념과 캐쉬 계층구조(CacheHierarchy)에대하여 설명하시오.", "sourcePage": 7, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-3-5", "round": 98, "session": 3, "number": 5, "text": "생체인식기법의 개념 및 구현 기법들의 특징에 대하여 설명하시오.", "sourcePage": 7, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-3-6", "round": 98, "session": 3, "number": 6, "text": "검색엔진을 정의하고 이를 색인어 구성절차 중심으로 설명하시오.", "sourcePage": 7, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-4-1", "round": 98, "session": 4, "number": 1, "text": "위치기반서비스(LBS:LocationBasedService)를정의하고,이를구현하는여러가지 방법과 응용 분야에 대하여 설명하시오.", "sourcePage": 8, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-4-2", "round": 98, "session": 4, "number": 2, "text": "비디오 압축(VideoCompression)기술을I-프레임,P-프레임,B-프레임의개념을 중심으로 설명하시오.", "sourcePage": 8, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-4-3", "round": 98, "session": 4, "number": 3, "text": "해쉬 테이블(HashTable)의개념과 장단점, 활용분야 및 충돌 해결(Collision Resolution)의여러가지기법에대하여 설명하시오.", "sourcePage": 8, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-4-4", "round": 98, "session": 4, "number": 4, "text": "디지털 서명(DigitalSignature)에대해정의하고이를구현하는 각 기법을 설명 하시오.", "sourcePage": 8, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-4-5", "round": 98, "session": 4, "number": 5, "text": "데이터베이스에서의 무결성(Integrity)개념과종류,그리고무결성을 유지하는 방법에 대하여 설명하시오.", "sourcePage": 8, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "98-4-6", "round": 98, "session": 4, "number": 6, "text": "논문의유사성 평가에 활용할 수있는 체계화된 방법에 대하여 설명하시오.", "sourcePage": 8, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-1-1", "round": 104, "session": 1, "number": 1, "text": "지능형 CCTV의 특징과 설치 시 고려하여야 할 사양 (Specification)에대하여 설명 하시오 .", "sourcePage": 27, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-1-2", "round": 104, "session": 1, "number": 2, "text": "타임서버의 필요성 및 도입 시 고려사항에 대하여 설명하시오 .", "sourcePage": 27, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-1-3", "round": 104, "session": 1, "number": 3, "text": "xHTML (E xtensible Hypertext Markup Language)", "sourcePage": 31, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-1-4", "round": 104, "session": 1, "number": 4, "text": "개인정보관리책임자 (CPO:ChiefPrivacyOfficer)에대하여 설명하시오 .", "sourcePage": 27, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-1-5", "round": 104, "session": 1, "number": 5, "text": "Mobile UX!U I(User Experience / User Interface)", "sourcePage": 31, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-1-6", "round": 104, "session": 1, "number": 6, "text": "TCP의 Three-wayHandshaking절차에 대하여 설명하시오 .", "sourcePage": 27, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-1-7", "round": 104, "session": 1, "number": 7, "text": "PLD(Programmable Logic Device)", "sourcePage": 31, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-1-8", "round": 104, "session": 1, "number": 8, "text": "센서 네트워크에서의 네트워크 경로제어에 대하여 설명하시오 .", "sourcePage": 27, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-1-9", "round": 104, "session": 1, "number": 9, "text": "지 능형 플랫폼 관리 인터페이스 (IPMI:IntelligentPlatformManagementInterface)에 대하여 설명하시오 .", "sourcePage": 27, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-1-10", "round": 104, "session": 1, "number": 10, "text": "BLE (B luetooth Low Energy) 1l. Cloud PVR(Personal Video Recorder)", "sourcePage": 31, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-1-11", "round": 104, "session": 1, "number": 11, "text": "데이터 거래소에 대하여 설명하시오 .", "sourcePage": 27, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-1-12", "round": 104, "session": 1, "number": 12, "text": "ISO 26262(FunctionalSafety)에대하여 설명하시오 .", "sourcePage": 27, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-1-13", "round": 104, "session": 1, "number": 13, "text": "1\\ αC/DC(Modified Condition / Decision Coverage)", "sourcePage": 31, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-2-1", "round": 104, "session": 2, "number": 1, "text": "Bubblesort알고리즘에 대하여 다음 내용을 설명하시오 .(오름차순 기준 ) 1)flag를 두지 않는 경우와 flag를 두는 경우로 나누어 설명하고 ,flag를 두는 이유를 설명하시오 . 2)다음 키 값을 갖는 파일을 Bubblesort알고리즘을 적용하여 sort하는 과정을 보이시오 .(n=8:30,50,10,80,40,60,70,90)", "sourcePage": 28, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-2-2", "round": 104, "session": 2, "number": 2, "text": "공통감리절차 중 시정조치확인 과정에 대하여 설명하시오 .", "sourcePage": 28, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-2-3", "round": 104, "session": 2, "number": 3, "text": "네 트워크 모델에서 활용되는 캡슐화와 역캡슐화 ,다중화와 역다중화에 대하여 설명하시오 .", "sourcePage": 28, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-2-4", "round": 104, "session": 2, "number": 4, "text": "멀티 프로세서 시스템의 구성형태를 제시하고 ,공유 메모리와 분산 메모리를 사용 하는 경우의 장단점을 비교하시오 .", "sourcePage": 28, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-2-5", "round": 104, "session": 2, "number": 5, "text": "정보보호 인증을 위해 정보보호관리체계 (ISMS :InformationSecurityManagement System)·개인정보보호관리체계 (PIMS :PersonalInformationManagementSystem)· 개인정보보호인증제 (PIPL :PersonalInformationProtectionLevel)가 운영되고 있는 가운데 방송통신위원회의 ISMS·PIMS·PIPL을 통합한 ISMS-P(가칭 )와 금 융위원회의 F-ISMS의 도입 논의로 정보보호 인증제도의 중복성이 증가될 수 있다 .정 보보호 인증의 중복 투자를 방지하고 효율성과 실효성을 높이기 위한 방안을 제시하시오 .", "sourcePage": 28, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-2-6", "round": 104, "session": 2, "number": 6, "text": "최근 금융권에서는 암호화를 전사 구간으로 확대하기 위해 PoC(ProofofConcept)를 진행하고 있다 .PoC,Pilottest,BMT(BenchmarkTest)의 주요 특징과 차이점에 대하여 비교 설명하시오 .", "sourcePage": 28, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-3-1", "round": 104, "session": 3, "number": 1, "text": "소프트웨어개발방법론에 있어서 방법론 테일러링 (Tailoring)의 필요성과 테일러링 시 고려사항을 설명하시오 .", "sourcePage": 29, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-3-2", "round": 104, "session": 3, "number": 2, "text": "PMO(ProjectManagementOfficer)의 기능 중 범위관리 ,일정관리 ,인적자원관리 , 위험관리 ,의사소통관리 기능에 대하여 각 기능의 정의 ,주요단계 ,관리상 주의사항을 설명하시오 .", "sourcePage": 29, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-3-3", "round": 104, "session": 3, "number": 3, "text": "CPU의 파이프라인 처리 시에 발생할 수 있는 구조적 해저드와 데이터 해저드 ,제어 해저드를 설명하시오 .", "sourcePage": 29, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-3-4", "round": 104, "session": 3, "number": 4, "text": "가상화를 실현하기 위해 OS와 하드웨어 사이에 구현하는 VMM(VirtualMachine Monitor)에 대하여 설명하고 ,I/O가상화를 구현하기 위한 방안을 3가지 제시하시오 .", "sourcePage": 29, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-3-5", "round": 104, "session": 3, "number": 5, "text": "기업이 업무연속성과 복구 우선순위 ,목표를 결정하기 위한 공식적이고 문서화된 업무영향평가 절차를 구축 ,이행 및 유지하기 위해 수행해야 하는 활동과 조 직의 제 품과 서비스를 제공하는 활동이 중단되 었을 때의 영향 추산에 필요한 활동에 대하여 설명하시오 .", "sourcePage": 29, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-3-6", "round": 104, "session": 3, "number": 6, "text": "최근 정 부가 발표한 국가 재난안전통신 망(PS-LTE)의 기 술적 특징과 전용 망,상용 망 구축방식에 따른 장단점을 설명하시오 .", "sourcePage": 29, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-4-1", "round": 104, "session": 4, "number": 1, "text": "데이터 베이스의 회복기법 (Recovery)에 대하여 다음 내용을 설명하시오 1)Redo와 Undo 2)로 그기반 회복기법 3)체크 포인트 회복기법 4)그림자페이지 회복기법", "sourcePage": 30, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-4-2", "round": 104, "session": 4, "number": 2, "text": "게임제 작의 한 과정에 속하는 게임사운드를 정의하고 게임사운드의 일 부인 게임음 악의 구성과 그 특징 및 게임음 악 제 작과정을 설명하시오 .", "sourcePage": 30, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-4-3", "round": 104, "session": 4, "number": 3, "text": "웹 서버의 다중화 시에 활용하는 로드 밸런서 (LoadBalancer,부하분산기 )에 대하여 설명하고 ,L4 스위치와 L7 스위치를 사용하는 경우의 장단점을 설명하시오 .", "sourcePage": 30, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-4-4", "round": 104, "session": 4, "number": 4, "text": "VLA N의 개 념에 대하여 설명하고 ,서버 팜을 구축하는 기 술인 포트 VLA N과 태그 VLA N 기 술에 대하여 비교 설명하시오 .", "sourcePage": 30, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-4-5", "round": 104, "session": 4, "number": 5, "text": "운 영체제 내 부 모 듈 중 Dispatcher의 주요 기능과 동 작 과정을 도식화하여 설명하시오 .", "sourcePage": 30, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "104-4-6", "round": 104, "session": 4, "number": 6, "text": "최 근 잇따르고 있는 재난 안전 사고를 예방하기 위하여 집적정보통신시설을 운영 ·관리 하는 사업자가 취하여야 하는 보호조치의 세 부적 기준 등 집적정보통신시설 보호를 위해 필 요한 사항에 대하여 설명하시오 .", "sourcePage": 30, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "105-2-1", "round": 105, "session": 2, "number": 1, "text": "국가재난 안전통신망을 구축하고자 한다. 현재 국내의 무선통신 이용시 문제점과 대책을 설명하시오.", "sourcePage": 32, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "105-2-2", "round": 105, "session": 2, "number": 2, "text": "WiFi 기반 실내 외 위치 추적기술에 대하여 설명하시오， 3 다음은 마이크로 커널의 일부분이다 알고리즘의 의미와 Co ntexLSwitchO 내부 메카니즘을 설 명하시오. vo id Scheduler( void) { tl -p ri = current task (RUNNING state)'s priority; t2 -p ri = highe st priority in th e Ready li s t; if ( tl -p ri < t2_pri) call ContexLSwitchO; e lse ; /* do nothing */ (참고사항 CPU , MEMORY , Task - l , Task - 2 , .. . ,Task - n , stack , TCB(Task ControI B! ock) , Priority , Status , Stack Base Address , CPU registers) 4 소스코드 형상관리 (Source Code Configuration Management) 업무 프로세스를 설정 ( Setup) 하고 형 상통제 (Configuration Contro l) 업 무흐름도 (Work Flow) 에 대 하여 설명하 시오.", "sourcePage": 33, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "105-2-3", "round": 105, "session": 2, "number": 3, "text": "사이버보안 활동을 개발단계와 운영 및 유지보수 단계로 구분하고， 보안관리 정책 및 체계， 인적(사원)관리， 개발내용 /결 과관리， 시설관리 및 정보통신망 관리항목에 대하여 체크리스트를 작성하시오.", "sourcePage": 32, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "105-2-4", "round": 105, "session": 2, "number": 4, "text": "기능안전 (Functional Safety) 분야의 소프트웨어 개발환경 구축을 위하여， 상용 소프트웨어 (Cornrnercial Software) 도구를 품질평가 (Tool Qu alification) 한 후 구매하여 사용하고자 한다. 상용 소프트혜어 도구의 품질평가 방법 및 프로세스에 대하여 설명하시오.", "sourcePage": 32, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "105-2-5", "round": 105, "session": 2, "number": 5, "text": "실시간 시스랩 구축에 있어， 커널 (KemeD 의 안전기능 (Safety Function) 을 정의하고， 이 를 평가하기 위한 핵심 시험대상 및 항목에 대하여 설명하시오.", "sourcePage": 32, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "105-2-6", "round": 105, "session": 2, "number": 6, "text": "OTT(Over The Top) 기술이 ICT (I nforrnation Comrnurucation Technology) 산업에 미치는 영향을 진입장벽， 구매자 협상력， 공급자 협상력， 대체재 (Substitute Goods) 및 기존경쟁 등 5 가지 경쟁요인 측면 에서 설명하시오.", "sourcePage": 34, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "105-4-1", "round": 105, "session": 4, "number": 1, "text": "RFID 응용인터페이스의 설계 원칙에 대하여 설명하시오", "sourcePage": 35, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "105-4-2", "round": 105, "session": 4, "number": 2, "text": "LTE-U 와 WiFi 차이점에 대하여 설명하시오.", "sourcePage": 35, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "105-4-3", "round": 105, "session": 4, "number": 3, "text": "FPGA(Field Programmable Gate Array) 디지털 설계， 프로그래빙， 시율레이션 및 다운로드 (Download) 과정을 설명하시오", "sourcePage": 35, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "105-4-4", "round": 105, "session": 4, "number": 4, "text": "하자보증 (Warranty) 과 유지 보수 (Maintenance) 를 구분하고， 소프트웨 어 유지 보수 유형 (긴급 유지보수， 수정 유지보수， 적웅 유지보수， 완전 유지보수)과 보고 및 행정 절차에 대하여 설명하시오.", "sourcePage": 35, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "105-4-5", "round": 105, "session": 4, "number": 5, "text": "사물인터넷(I oT : Intemet of Things) 시스템의 TRUTechnology Readiness Leve j)에 대하여 설명하시오.", "sourcePage": 35, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "105-4-6", "round": 105, "session": 4, "number": 6, "text": "NTP(Network Time Protoco j)의 정보보호 취약점과 대응방안에 대하여 설명하시오.", "sourcePage": 35, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-1-1", "round": 107, "session": 1, "number": 1, "text": "PoE(Power over Ethernet)", "sourcePage": 36, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-1-2", "round": 107, "session": 1, "number": 2, "text": "020(Online to Offline)", "sourcePage": 36, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-1-3", "round": 107, "session": 1, "number": 3, "text": "IP (I nternet Protoco]) 카메 라", "sourcePage": 36, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-1-4", "round": 107, "session": 1, "number": 4, "text": "ESS (E nergy Storage System)", "sourcePage": 36, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-1-5", "round": 107, "session": 1, "number": 5, "text": "SDN(Software Defined Network)", "sourcePage": 36, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-1-6", "round": 107, "session": 1, "number": 6, "text": "CR(Cognitive Radio)", "sourcePage": 36, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-1-7", "round": 107, "session": 1, "number": 7, "text": "스 마 트 OTP(One Time Password)", "sourcePage": 36, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-1-8", "round": 107, "session": 1, "number": 8, "text": "ARP 스푸핑의 탐지기법과 대응", "sourcePage": 36, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-1-9", "round": 107, "session": 1, "number": 9, "text": "모바일 웹 (Mobile Web) , 모바일 엠 (Mobile App) , 하이브리드 엠(H ybrid App)", "sourcePage": 36, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-1-10", "round": 107, "session": 1, "number": 10, "text": "CMM I( Capability Maturity Model Integration)", "sourcePage": 36, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-1-11", "round": 107, "session": 1, "number": 11, "text": "]AD (J oint Application De s ig n/ Development) 12 . S ηV 프 로젝트의 WBS (W ork Breakdown Sσucture) 100% 규칙 (Rule)", "sourcePage": 36, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-1-13", "round": 107, "session": 1, "number": 13, "text": "IEEE 802.11ac", "sourcePage": 36, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-2-1", "round": 107, "session": 2, "number": 1, "text": "IoT (I nternet of Things) 의 구성요소， 계층 및 활용사례에 대하여 설명하시오.", "sourcePage": 37, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-2-2", "round": 107, "session": 2, "number": 2, "text": "본사와 지사간에 인터넷과 인트라넷을 분리 운영하여 망을 구성하고자 한다. 보안 설비 망구성도를 간단히 표시하고， 보안설비의 종 류 및 역할에 대하여 설명하시오，", "sourcePage": 37, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-2-3", "round": 107, "session": 2, "number": 3, "text": "192.168.4 .0 ~ 192.168.7.0/24 IP 대역을 슈퍼네팅하여 NW ID , Subnet Ma sk, 유효 IP 호스트 수 를 산 출 하시 오.", "sourcePage": 37, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-2-4", "round": 107, "session": 2, "number": 4, "text": "IMT - 2020/5G 에 대하여 설명하시오", "sourcePage": 37, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-2-5", "round": 107, "session": 2, "number": 5, "text": "IEEE 802 .l li 의 동 장배경을 설명하고 인 증과 키교환 방식을 설명하시오.", "sourcePage": 37, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-2-6", "round": 107, "session": 2, "number": 6, "text": "재난재해 발생시 피해절감을 위한 데이터 큐레이션 (Data Curation) 분야와 주요 활동에 대하여 설명하시오.", "sourcePage": 37, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-3-1", "round": 107, "session": 3, "number": 1, "text": "공얀인증의 의무사용 폐지에 따른 긍정적과 부정적 영향을 설명하고， 대체인증수단 및 활 성화 방안을 설명하시오.", "sourcePage": 38, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-3-2", "round": 107, "session": 3, "number": 2, "text": "S 八 V 프로젝트의 규모척도인 기능접수 (Fun c ti on P o int ) 의 장단점을 설명하고 ， LOC( Line Of Code) 와 COCOMO (COns tru ctive COst M O de]) 와의 차 이 를 설명하시오 .", "sourcePage": 39, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-3-3", "round": 107, "session": 3, "number": 3, "text": "SSD(So lid State D ri ve) 에 대해 다음을 설명하시오. CD 구성요소와 SS D 컨트롤러의 동작 CZl SS D 펌웨어의 기능 @ VO Pat h 의 방식 @ 향후 가 능 진화 방 향", "sourcePage": 39, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-3-4", "round": 107, "session": 3, "number": 4, "text": "산업분야에 적용되는 엄 베디 드 소프트웨어의 품질특정을 설명하고， 산업현장 에 서 임베디드 소프트웨어 테스탱에 있어 발생하는 문제점을 3 가지 나열하시오 5 소프트웨어 시스템을 공격하는 부채널 공격의 유형을 서술하고， 공격에 대한 대웅방법을 설명하시오. 6 . IT 포트폴리오의 개념과 유형 ， 관리활동을 설명하시오 .", "sourcePage": 39, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-3-5", "round": 107, "session": 3, "number": 5, "text": "3 단계 IT 융합 확산전략으로 제시된 생활밀착형 신산업 IT 융합의 개념과 범위에 대하여 설명하시오.", "sourcePage": 38, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "107-3-6", "round": 107, "session": 3, "number": 6, "text": "MIMO(Multi Input Multi Output) 와 OFDM(Orthogonal Frequency Division Multiplexing) 기 술 을 함께 사용될 경우 시스템과 사용자 측 면에서 고속 대용량화 하 는 과정을 설명하시오.", "sourcePage": 38, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-1-1", "round": 108, "session": 1, "number": 1, "text": "국산 암호화알고리즘 중 LEA(LightweightEncryptionAlgorithm)", "sourcePage": 40, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-1-2", "round": 108, "session": 1, "number": 2, "text": "핀테크 (Fin-tech)의블록체인기술 (BlockchainSecurityTec0+hnology)", "sourcePage": 40, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-1-3", "round": 108, "session": 1, "number": 3, "text": "로보어드바이저 (Robo-advisor)", "sourcePage": 40, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-1-4", "round": 108, "session": 1, "number": 4, "text": "HDR(HighDynamicRangeimaging)", "sourcePage": 40, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-1-5", "round": 108, "session": 1, "number": 5, "text": "운영체제의 크리티컬 섹션 (Criticalsection)구현방법2가지", "sourcePage": 40, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-1-6", "round": 108, "session": 1, "number": 6, "text": "RM(RateMonotonic)스케줄링과EDF(EarliestDeadlineFirst)스케줄링알고리즘", "sourcePage": 40, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-1-7", "round": 108, "session": 1, "number": 7, "text": "기계 학습 (Machinelearning)의개념및응용분야", "sourcePage": 40, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-1-8", "round": 108, "session": 1, "number": 8, "text": "핫 스탠바이 (Hot-standby)및콜드스탠바이 (Cold-standby)", "sourcePage": 40, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-1-9", "round": 108, "session": 1, "number": 9, "text": "MOOC(MassiveOnlineOpenCourse)", "sourcePage": 40, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-1-10", "round": 108, "session": 1, "number": 10, "text": "전자정부프레임워크 (e-Governmentframework)버전별차이점", "sourcePage": 40, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-1-11", "round": 108, "session": 1, "number": 11, "text": "스마트카 (Smart-Car)", "sourcePage": 40, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-1-12", "round": 108, "session": 1, "number": 12, "text": "HMD(HeadMountedDisplay)와가상현실(VirtualReality)", "sourcePage": 40, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-1-13", "round": 108, "session": 1, "number": 13, "text": "HTML5", "sourcePage": 40, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-2-1", "round": 108, "session": 2, "number": 1, "text": "개인정보보호법 제30조에 따른 “개인정보 처리방침 ”에 반드시 포함되어야 하는 사항을 5가지 이상 설명하시오 .", "sourcePage": 41, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-2-2", "round": 108, "session": 2, "number": 2, "text": "네트워크 기능 가상화 (NetworkFunctionVirtualization)를 이용한 네트워크 슬라이싱 (NetworkSlicing)방안을 설명하시오 .", "sourcePage": 41, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-2-3", "round": 108, "session": 2, "number": 3, "text": "클럭 (Clock)의 상승 에지 (RisingEdge)에서 작동하는 D 플립플롭 (Flip-flop)을 이용하여 다음의 순서를 반복하는 동기 카운터 회로를 설계하시오 .", "sourcePage": 41, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-2-4", "round": 108, "session": 2, "number": 4, "text": "멀티태스킹 (Multi-tasking)을지원하는 운영체제에서 태스크 관리 방법을 설명하고 태스크간의 문맥전환 (Contextswitching)과정을 스택 (Stack),스택포인터 (SP), CPU내 레지스터 (Register)를포함하여 기술하시오 .", "sourcePage": 41, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-2-5", "round": 108, "session": 2, "number": 5, "text": "국내의 재난 및 안전관리가 매우 중요한 영역으로 부상하고 있다 . 재난 및 안전관리를 위한 ICT측면에서의 핵심기술을 설명하시오 .", "sourcePage": 41, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-2-6", "round": 108, "session": 2, "number": 6, "text": "3D 프린팅 기술이 의료분야를 포함한 각종 디자인 ,시제품 생산에 많은 주목을 받고 있는 추세이다 .3D 프린팅 기술에 대해 설명하고 ,3D 프린팅을 하기 위한 모델링 기법을 기술하시오 .", "sourcePage": 41, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-3-1", "round": 108, "session": 3, "number": 1, "text": "호환성 확보를 위한 컴퓨터 프로그램 코드의 역공학 (ReverseEngineering)허용을 저작권 측면에서 설명하시오 .", "sourcePage": 42, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-3-2", "round": 108, "session": 3, "number": 2, "text": "초연결 사회 구현을 위한 기술인 IoT(InternetofThings)와CPS(Cyber－Physical Systems)를 비교 설명하시오 .", "sourcePage": 42, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-3-3", "round": 108, "session": 3, "number": 3, "text": "삼중구조 (TripleModularRedundancy)는고장을 탐지하고 복구할 수 있는 전통적인 고장허용 (Faulttolerance)기법중의 하나이다 .삼중구조를 1비트의 값을 저장할 수 있는 메모리 셀 (memorycell)에적용하였을 때 메모리 값의 오류를 탐지하고 복구하는 회로를 설계하고 ,복구과정을 설명하시오 .", "sourcePage": 42, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-3-4", "round": 108, "session": 3, "number": 4, "text": "세마포어 (Semaphore)를이용한 리소스 공유 방법과 태스크간 동기화 방법에 대하여 설명하시오 .", "sourcePage": 42, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-3-5", "round": 108, "session": 3, "number": 5, "text": "네트워크 라우팅 기법 중 거리 벡터라우팅 (DistanceVectorRouting)과링크스테이트 라우팅 (LinkStateRouting)기법의 장 ·단점을 비교하여 설명하시오 .", "sourcePage": 42, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-3-6", "round": 108, "session": 3, "number": 6, "text": "사이버 상 채팅이나 모바 일을 활용한 피싱 ,그 외에 사회적인 지위 ,신분을 악용한 금전 요구 등 개인정보를 침해하고 ,민감한 정보를 악용하는 사례가 많이 발생하고 있다 .위와 같은 개인정보침해를 예방하기 위한 방안에 대해 설명하시오 .", "sourcePage": 42, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-4-1", "round": 108, "session": 4, "number": 1, "text": "전자 금융과 핀테크를 비교하고 OPENAPI를 이용한 금융데이터 공유 활성화를 설명하시오 .", "sourcePage": 43, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-4-2", "round": 108, "session": 4, "number": 2, "text": "프로그 래매 틱 바잉(ProgrammaticBuying)을통한 모바 일 광고 방안을 설명하시오 .", "sourcePage": 43, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-4-3", "round": 108, "session": 4, "number": 3, "text": "3개 태스크 (task1,task2,task3)가실행되고이 들의 우선순위는 task1> task2>task3 이다 .우 선순위 역전 (PriorityInversion)이발생하는 경우와 이를 해결하기 위한 방법을 위 3개 태스크를 예로 들어 설명하시오 .", "sourcePage": 43, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-4-4", "round": 108, "session": 4, "number": 4, "text": "CPU의 동작을 감시하는 워치독 타이 머(Watchdogtimer)에 대하여 기술하고 하드 웨어 구현방법을 설명하시오 .", "sourcePage": 43, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-4-5", "round": 108, "session": 4, "number": 5, "text": "최근 프로 젝트의 위험성을 최소화하기 위해 PMO(ProjectManagementOffice) 활성화에 대한 방안이 여러 분야에서 논의되고 있다 .PMO에 대해서 기술하고 , 정보시스 템감리 유 형 중 상주 감리와의 차이점을 설명하시오 .또한 PMO를 활성화하기 위한 방안에 대해 설명하시오 .", "sourcePage": 43, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "108-4-6", "round": 108, "session": 4, "number": 6, "text": "아래 암호화 기법을 설명하시오 . 가 .블록 (Block)및스트 림(Stream)암호화 기법 나 .워터마크 (Watermark)", "sourcePage": 43, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-1-1", "round": 110, "session": 1, "number": 1, "text": "SDRAM(SynchronousDRAM)", "sourcePage": 44, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-1-2", "round": 110, "session": 1, "number": 2, "text": "마이크로 에너지 수확 (MicroEnergyHarvesting)", "sourcePage": 44, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-1-3", "round": 110, "session": 1, "number": 3, "text": "L2스위치 (L2Switch)", "sourcePage": 44, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-1-4", "round": 110, "session": 1, "number": 4, "text": "MRAM(MagnetoresistiveRAM:강자성메모리)", "sourcePage": 44, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-1-5", "round": 110, "session": 1, "number": 5, "text": "유헬스 케어 (u-Healthcare)", "sourcePage": 44, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-1-6", "round": 110, "session": 1, "number": 6, "text": "NoSQL(NotonlyStructuredQueryLanguage)", "sourcePage": 44, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-1-7", "round": 110, "session": 1, "number": 7, "text": "CDC(ChangeDataCapture)", "sourcePage": 44, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-1-8", "round": 110, "session": 1, "number": 8, "text": "DB옵티마이저 (DBOptimizer:DB질의최적화기)", "sourcePage": 44, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-1-9", "round": 110, "session": 1, "number": 9, "text": "사이버물리시스템 (CPS:Cyber-PhysicalSystem)", "sourcePage": 44, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-1-10", "round": 110, "session": 1, "number": 10, "text": "딥러닝(DeepLearning:심층학습)", "sourcePage": 44, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-1-11", "round": 110, "session": 1, "number": 11, "text": "랜섬웨어(Ransomware)", "sourcePage": 44, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-1-12", "round": 110, "session": 1, "number": 12, "text": "FEC(ForwardErrorCorrection)", "sourcePage": 44, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-1-13", "round": 110, "session": 1, "number": 13, "text": "스토리지 티어링 (StorageTiering)", "sourcePage": 44, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-2-1", "round": 110, "session": 2, "number": 1, "text": "데이터베이스 보안이 추구하는 3대 요소와 데이터의 무결성 저하 유형에 대하여 설명 하시오 .", "sourcePage": 45, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-2-2", "round": 110, "session": 2, "number": 2, "text": "가상현실 (VR:VirtualReality)과증강현실(AR:AugmentedReality)에대하여다음 내용을 설명하시오 . 1)VR과 AR정의 2)VR과 AR차이점 3)VR및 AR 사례", "sourcePage": 45, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-2-3", "round": 110, "session": 2, "number": 3, "text": "데이터 전송 오류가 발견된 경우 DataLinkLayer에서오류복구를 수행하는 절차에 대하여 설명하시오 .", "sourcePage": 45, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-2-4", "round": 110, "session": 2, "number": 4, "text": "버스 상에 여러 노드가 연결된 경우 이용될 수 있는 HDLC(High-levelDataLink Control)의동작모드를 설명하시오 .", "sourcePage": 45, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-2-5", "round": 110, "session": 2, "number": 5, "text": "UV EPROM(UltraVioletErasableProgrammableROM),EEPROM(Electrically ErasableProgrammableROM)및Flash메모리를쓰기(소거및 프로그램 )관점에서 비교 설명하시오 .", "sourcePage": 45, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-2-6", "round": 110, "session": 2, "number": 6, "text": "방화벽 ,침입탐지 시스템 (IDS:IntrusionDetectionSystem),침입방지시스템(IPS: IntrusionPreventionSystem)및웹방화벽의개념과기능을 설명하시오 .", "sourcePage": 45, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-3-1", "round": 110, "session": 3, "number": 1, "text": "재해복구 시스템의 개념과 구축유형에 따른 장·단점을 각각 설명하시오 .", "sourcePage": 46, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-3-2", "round": 110, "session": 3, "number": 2, "text": "스토리지 프로비저닝 (StorageProvisioning)의두가지방법을비교 설명하시오 .", "sourcePage": 46, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-3-3", "round": 110, "session": 3, "number": 3, "text": "LOD(LinkedOpenData)에대하여다음 내용을 설명하시오 . 1)LOD의 개념 2)문서 웹(Web)과LOD에 의한 데이터 웹의 차이점 3)LOD기술 요소", "sourcePage": 46, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-3-4", "round": 110, "session": 3, "number": 4, "text": "인더스트리 (Industry)4.0에대하여다음내용을 설명하시오 . 1)인더스트리 4.0의배경 2)인더스트리 4.0의핵심 기술 요소 3)인더스트리 4.0의기대 효과", "sourcePage": 46, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-3-5", "round": 110, "session": 3, "number": 5, "text": "SIP(SessionInitiationProtocol)의개념을설명하고,세션(Session)의생성과정을설명 하시오 .", "sourcePage": 46, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-3-6", "round": 110, "session": 3, "number": 6, "text": "페이지 방식을 이용하는 가상 메모리에서 가상주소 (Virtualaddress)를주기억장치 주소인 물리주소 (Physicaladdress)로변환하는과정을 페이지 테이블 (PageTable) 및 TLB(TranslationLookasideBuffer)를이용하여설명하시오.", "sourcePage": 46, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-4-1", "round": 110, "session": 4, "number": 1, "text": "대칭 암호화와 비대칭 (공개키)암호화를 각각 설명하고 ,비교하시오 .", "sourcePage": 47, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-4-2", "round": 110, "session": 4, "number": 2, "text": "운영체제에서 문맥 (context)의내용,문맥교환(contextswitch)의과정및문맥교환이 발생하는 조건을 설명하시오 .", "sourcePage": 47, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-4-3", "round": 110, "session": 4, "number": 3, "text": "DB설계에 있어서 PrimaryKey와UniqueIndex의특성을비교하고 ,PrimaryKey 사용 시의 장점에 대하여 설명하시오 .", "sourcePage": 47, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-4-4", "round": 110, "session": 4, "number": 4, "text": "통신망(CommunicationNetwork)장치들의물리적구성형태 및 각각의 특징에 대하여 설명하시오 .", "sourcePage": 47, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-4-5", "round": 110, "session": 4, "number": 5, "text": "FDS(FraudDetectionSystem)의개념,구성요소및기능을설명하시오 .", "sourcePage": 47, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "110-4-6", "round": 110, "session": 4, "number": 6, "text": "가상화 환경에서 데이터 백업방법 2가지를 설명하시오 .", "sourcePage": 47, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-1-1", "round": 111, "session": 1, "number": 1, "text": "라운드 로빈 (RoundRobin)과EDF(EarliestDeadlineFirst)스케줄링", "sourcePage": 48, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-1-2", "round": 111, "session": 1, "number": 2, "text": "FPGA(FieldProgrammableGateArray)", "sourcePage": 48, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-1-3", "round": 111, "session": 1, "number": 3, "text": "메모리 단편화 (MemoryFragmentation)의원인및해결방안", "sourcePage": 48, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-1-4", "round": 111, "session": 1, "number": 4, "text": "운영체제 (OS)에서 우선순위 상속(PriorityInheritance)", "sourcePage": 48, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-1-5", "round": 111, "session": 1, "number": 5, "text": "Openstack", "sourcePage": 48, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-1-6", "round": 111, "session": 1, "number": 6, "text": "CNN(ConvolutionalNeuralNetworks)", "sourcePage": 48, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-1-7", "round": 111, "session": 1, "number": 7, "text": "XMLSchema", "sourcePage": 48, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-1-8", "round": 111, "session": 1, "number": 8, "text": "최적의 UX(UsereXperience)구현을위한 세가지 조건 (유용성 ,사용성 ,감성 )", "sourcePage": 48, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-1-9", "round": 111, "session": 1, "number": 9, "text": "네트워크 전송계층 (TransportLayer)역할", "sourcePage": 48, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-1-10", "round": 111, "session": 1, "number": 10, "text": "크로스사이트 스크립트 (XSS:CrossSiteScript)", "sourcePage": 48, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-1-11", "round": 111, "session": 1, "number": 11, "text": "디지털 포렌식 (DigitalForensic)", "sourcePage": 48, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-1-12", "round": 111, "session": 1, "number": 12, "text": "디지털 트윈 (DigitalTwin)", "sourcePage": 48, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-1-13", "round": 111, "session": 1, "number": 13, "text": "ObserverPattern", "sourcePage": 48, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-2-1", "round": 111, "session": 2, "number": 1, "text": "클라우드 컴퓨팅의 보안 기술 중 검색가능 암호화 (SearchableEncryption)와프라이버시 보존형 데이터 마이닝 (PrivacyPreservingDataMining:PPDM)에대하여 설명하시오 .", "sourcePage": 49, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-2-2", "round": 111, "session": 2, "number": 2, "text": "정보시스템 개발에 있어 ,사용성 평가 ,인터페이스 설계 ,정보구조 설계 ,웹 디자인 등 다양한 분야에서 HCI(HumanComputerInterface)관련 업무가 진행되고 있다 . 가 .HCI에서 사용자 분석을 위해 적용되는 사용자 모형에 대하여 설명하시오 . 나 .사용자 모형 중 페르소나 모형 (PersonaModel)을통해 사용자를 분석하는 방법을 설명하시오 .", "sourcePage": 49, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-2-3", "round": 111, "session": 2, "number": 3, "text": "하둡 분산파일시스템 (HDFS:HadoopDistributedFileSystem)의특징및 구조에 대하여 설명하고 ,구성요소인 네임노드 ,데이터 노드의 역할에 대하여 설명하시오 .", "sourcePage": 49, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-2-4", "round": 111, "session": 2, "number": 4, "text": "발주기관의 IT담당부서 책임자로써 ,프로젝트 검수단계에 최종 산출물이 현업부서의 최초 요구사항에 맞게 구현되었는지를 보장하기 위한 방안을 제시하시오 .", "sourcePage": 49, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-2-5", "round": 111, "session": 2, "number": 5, "text": "스마트 미디어기기의 급속한 대중화로 인해 무선충전에 대한 수요가 확대되고 있다 . 무선충전기술을 설명하고 응용 분야 및 동향을 기술하시오 .", "sourcePage": 49, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-2-6", "round": 111, "session": 2, "number": 6, "text": "클럭의 상승에지 (risingedge)에서천이하는아래의 Mealy상태 머신을 VHDL(VHSIC HardwareDescriptionLanguage)로구현하시오. 입력:x,clk,reset 출력(2bit):y", "sourcePage": 50, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-3-1", "round": 111, "session": 3, "number": 1, "text": "우선순위 (Priority)기반의 실시간 운영체제 (Real-timeOS)에서 태스크 (Task)실행 중에 인터럽트 (Interrupt)가발생하였을 때 ,인터럽트 서비스 루틴 (ServiceRoutine)이 실행되기까지의 과정과 인터럽트 서비스 루틴 수행이 끝난 후 복귀되는 과정을 설명 하시오 .", "sourcePage": 51, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-3-2", "round": 111, "session": 3, "number": 2, "text": "프로젝트 관리 국제표준인 ISO21500에는관리 주제별로 단계별 수행 프로세스에 대하여 명시하고 있다 . 가 .ISO21500에서 범위관리를 위해 기획 단계와 통제 단계에 수행하는 세부 활동에 대하여 설명하시오 . 나 .작업분류체계 (WBS:WorkBreakdownStructure)에대하여 설명하시오 . (정의 ,주요 투입물 ,작성방법 등) 다 .프로젝트 수행 경험을 통해 WBS가 범위관리 외에 일정관리 ,의사소통관리 등에 어 떻게 활용되는지 사례를 제시하시오 .", "sourcePage": 51, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-3-3", "round": 111, "session": 3, "number": 3, "text": "테스트 설계 기법 중 명세기반 기법 (Specification-basedTechnique)에대하여설명하시오.", "sourcePage": 51, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-3-4", "round": 111, "session": 3, "number": 4, "text": "PipelineHazard의유형과 제 거방안에 대해 기술하시오 .", "sourcePage": 51, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-3-5", "round": 111, "session": 3, "number": 5, "text": "소프트 웨어 재사용성을 통해 생산성을 향상시 키기 위한 방안을 설계 ,구현 ,유지보수 단계에서 구체적 으로 설명하시오 .", "sourcePage": 51, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-3-6", "round": 111, "session": 3, "number": 6, "text": "다음은 컴퓨터에서 사용되는 제품에 대해 여러 개의 주문서가 접수된 내용을 보여주는 “주문목록”초기 테이 블이다 .각각의 물음에 답하시오 . 제 품 제품명 재고 주문 수출 고 객 사업자 우선 주문 번호 수량 번호 여부 번호 번호 순위 수량 1001모 니터 1,990AB345 X 45203982011 150 1001모 니터 1,990AD347 Y 2341 - 3 600 1007마우스 9,702CA210 X 32802002128 1,200 1007마우스 9,702AB345 X 45203982011 300 1007마우스 9,702CB230 X 23415638923 390 1201스 피커 2,108CB231 Y 8320 - 2 80 가.1차 정 규화된 테이 블과 E-R다이어 그램을 표현하시오 . 나.2차 정 규화된 테이 블과 E-R다이어 그램을 표현하시오 . 다.3차 정 규화된 테이 블과 E-R다이어 그램을 표현하시오 .", "sourcePage": 52, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-4-1", "round": 111, "session": 4, "number": 1, "text": "외부 타이머 (Timer)를이용하여 마이크로프로세서 (Microprocessor)의동작을감시하는 워치독 타이머 (WatchdogTimer)를구현하고자 한다 .하드 웨어 (Hardware)를설계하고 , 마이크로프로세서 내부에서 실행해야하는 소프트 웨어 (Software)를설명하시오 .", "sourcePage": 53, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-4-2", "round": 111, "session": 4, "number": 2, "text": "DDoS공격의 인지 ,공격 유형 파 악,공격 유형에 따른 대응 방안에 대하여 설명하시오 .", "sourcePage": 53, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-4-3", "round": 111, "session": 4, "number": 3, "text": "IT프로젝트를 수행 함에 있어 프로젝트 내/외부에 많은 갈등이 있다 .이로 인해 프로 젝트의 성 패에 영향을 미 치게 된다 .PM의 입장에서 아래사항에 대해 기술하시오 . 가.갈등과 프로젝트 성과와의 관계 나.갈등의 요인 다.갈등의 해결방법", "sourcePage": 53, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-4-4", "round": 111, "session": 4, "number": 4, "text": "한국형 웹 콘텐츠 접근지 침에는 장애인이 비장 애인과 동등하게 웹 콘텐츠에 접근할 수 있도록 웹 콘텐츠를 제작하는 방법에 관하여 제시하고 있다 .아래의 4가지 원 칙에 따른 지 침과 검사항 목을 기술하시오 가.원 칙 1.인식의 용이성 (Perceivable) 나.원 칙 2.운용의 용이성 (Operable) 다.원 칙 3.이해의 용이성 (Understandable) 라.원 칙 4.견고성 (Robust)", "sourcePage": 53, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-4-5", "round": 111, "session": 4, "number": 5, "text": "A사는 노후화 된 서버의 기존시스템 (LegacySystem)을신 규시스템 (TargetSystem) 으로 이관 (Migration)작업을수행 하 려 한다 .아래의 내용을 설명하시오 . 가.주요 이관 대상 나.성 공적 시스템 이관 (Migration)을위한절차 다.주요 고 려 사항", "sourcePage": 53, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "111-4-6", "round": 111, "session": 4, "number": 6, "text": "컴퓨터 아키텍처 분야에서 Locality의개념에 대하여 설명하고 ,이를 활용한 사례를 제 시 하시오 .", "sourcePage": 53, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-1-1", "round": 113, "session": 1, "number": 1, "text": "간편결제", "sourcePage": 54, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-1-2", "round": 113, "session": 1, "number": 2, "text": "함수형 언어", "sourcePage": 54, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-1-3", "round": 113, "session": 1, "number": 3, "text": "CWE(CommonWeaknessEnumeration)", "sourcePage": 54, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-1-4", "round": 113, "session": 1, "number": 4, "text": "ConcolicExecution", "sourcePage": 54, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-1-5", "round": 113, "session": 1, "number": 5, "text": "Modbus", "sourcePage": 54, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-1-6", "round": 113, "session": 1, "number": 6, "text": "MR(MixedReality)", "sourcePage": 54, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-1-7", "round": 113, "session": 1, "number": 7, "text": "4D프린팅", "sourcePage": 54, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-1-8", "round": 113, "session": 1, "number": 8, "text": "FeRAM(FerroelectricRAM:강유전체메모리 )", "sourcePage": 54, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-1-9", "round": 113, "session": 1, "number": 9, "text": "웹 마이닝 (WebMining)", "sourcePage": 54, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-1-10", "round": 113, "session": 1, "number": 10, "text": "디지털 홀로그램", "sourcePage": 54, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-1-11", "round": 113, "session": 1, "number": 11, "text": "로봇 소프트웨어 플랫폼", "sourcePage": 54, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-1-12", "round": 113, "session": 1, "number": 12, "text": "O4O(OnlineforOffline)", "sourcePage": 54, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-1-13", "round": 113, "session": 1, "number": 13, "text": "SDDC(SoftwareDefinedDataCenter) 청렴은 건전한 국가 재정의 첫걸음", "sourcePage": 54, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-2-1", "round": 113, "session": 2, "number": 1, "text": "근거리 무선네트워크 기술 WPAN(WirelessPersonalAreaNetwork)의 Bluetooth, UWB,Zigbee를 비교하여 설명하시오 .", "sourcePage": 55, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-2-2", "round": 113, "session": 2, "number": 2, "text": "품질관리이론에서 프로세스 관리 관점의 PDCA(PlanDoCheckAction)Cycle에 대하여 설명하시오 .", "sourcePage": 55, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-2-3", "round": 113, "session": 2, "number": 3, "text": "웹 취약점 발견을 위해 사용하는 정적 분석기술과 동적 분석기술에 대하여 설명하고 , SQLInjection을 예로 정적 분석 결과를 동적 분석에서 활용하기 위한 방안제시 및 이 방법이 정적 분석의 어떤 단점을 보완하는지 설명하시오 .", "sourcePage": 55, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-2-4", "round": 113, "session": 2, "number": 4, "text": "업무에서 발생하는 정보유출을 DBMS,네트워크 ,파일 (또는 문서 ) 등 사고 유형과 이를 안전하게 유지하기 위한 보안 기술에 대하여 설명하시오 .", "sourcePage": 55, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-2-5", "round": 113, "session": 2, "number": 5, "text": "SCADA(SupervisoryControlandDataAcquisition)시스템의 개념을 설명하고 , 지능형 SCADA시스템과 비교하여 설명하시오 .", "sourcePage": 55, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-2-6", "round": 113, "session": 2, "number": 6, "text": "자율주행을 가능하게 하는 센서 및 통신기술에 대하여 설명하시오 . 청렴은 건전한 국가 재정의 첫걸음", "sourcePage": 55, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-3-1", "round": 113, "session": 3, "number": 1, "text": "4차 산업혁명 ‘퍼팩트 스톰 (PerfectStorm)’이 가져올 변화와 우리나라의 전망 및 대응방안에 대하여 설명하시오 .", "sourcePage": 56, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-3-2", "round": 113, "session": 3, "number": 2, "text": "최근에 인공지능 ,전자상거래 등의 분야에 많이 활용되고 있는 에이전트 (Agent)에 대하여 다음 각 물음을 설명하시오 . 가 .에이전트의 개념 ,구조 및 구성요소 나 .에이전트의 유형별 기술 비교 다 .에이전트의 활용분야 및 기술의 장 ․ 단점", "sourcePage": 56, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-3-3", "round": 113, "session": 3, "number": 3, "text": "FOSS(Freeandopen-sourcesoftware),Opensourcelicense종류 ,준수 방법 ,고지 의무 , 그리고 라이선스 양립성에 대하여 설명하시오 .", "sourcePage": 56, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-3-4", "round": 113, "session": 3, "number": 4, "text": "미들웨어 기반으로 구성된 기업 업무시스템에 대해 정적분석을 이용하여 테스트케이스 개수와 각 테스트케이스의 입력 값과 예상 결과 값을 생성하는 방법과 반복 테스트 시 문제점과 해결 방안에 대하여 설명하시오 .", "sourcePage": 56, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-3-5", "round": 113, "session": 3, "number": 5, "text": "검색엔진과 검색포탈에 대하여 설명하고 ,각각 차이점을 사례를 들어서 비교하여 설명하시오 .", "sourcePage": 56, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-3-6", "round": 113, "session": 3, "number": 6, "text": "AMI(AdvancedMeteringInfrastructure)핵심기술과 주요 통신방식에 대하여 설명하시오 . 청렴은 건전한 국가 재정의 첫걸음", "sourcePage": 56, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-4-1", "round": 113, "session": 4, "number": 1, "text": "양자 알고리즘이 현대 암호에 미치는 영향에 대해서 ‘Shor알고리즘 ’과 ‘Grover알고리즘 ’ 중심으로 설명하시오 .", "sourcePage": 57, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-4-2", "round": 113, "session": 4, "number": 2, "text": "클러스터링 (Clustering)의 개념과 주요목적 및 클러스터링의 장 ․ 단점과 발전 전망에 대하여 설명하시오 .", "sourcePage": 57, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-4-3", "round": 113, "session": 4, "number": 3, "text": "최근 정보보안이 이슈가 되고 있다 .2계 층 과 3계 층 어플리케이 션 각각의 특징 을 설명 하고 , 이들의 암호 키 관리와 키 의 안전한 교 환 방법에 대하여 설명하시오 .", "sourcePage": 57, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-4-4", "round": 113, "session": 4, "number": 4, "text": "4차 산업혁명과 더불 어 이슈가 되고 있는 플랫폼 전 략 과 플랫폼 비 즈니 스에 대한 다음 각 물음을 설명하시오 . 가 .플랫폼 전 략 과 플랫폼 비 즈니 스 차이점 나 .플랫폼 전 략 의 주요 기능 다 .플랫폼 비 즈니 스의 유형 및 향 후 방향", "sourcePage": 57, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-4-5", "round": 113, "session": 4, "number": 5, "text": "SmartFarm의 주요기능 및 기술에 대하여 설명하시오 .", "sourcePage": 57, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "113-4-6", "round": 113, "session": 4, "number": 6, "text": "임베 디 드 소프트웨어를 위한 OpenSEED에 대하여 설명하시오 . 청렴은 건전한 국가 재정의 첫걸음", "sourcePage": 57, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-1-1", "round": 114, "session": 1, "number": 1, "text": "선점형 스케줄링(PreemptiveScheduling)", "sourcePage": 58, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-1-2", "round": 114, "session": 1, "number": 2, "text": "CPU보안결함 중에서 멜트다운(Meltdown)", "sourcePage": 58, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-1-3", "round": 114, "session": 1, "number": 3, "text": "TPU(TensorProcessingUnit)", "sourcePage": 58, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-1-4", "round": 114, "session": 1, "number": 4, "text": "InformationHiding", "sourcePage": 58, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-1-5", "round": 114, "session": 1, "number": 5, "text": "PMI(PrivilegeManagementInfrastructure)", "sourcePage": 58, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-1-6", "round": 114, "session": 1, "number": 6, "text": "MPTCP(MultipathTCP)", "sourcePage": 58, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-1-7", "round": 114, "session": 1, "number": 7, "text": "ZeroUI", "sourcePage": 58, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-1-8", "round": 114, "session": 1, "number": 8, "text": "TLB(TranslationLookasideBuffer)", "sourcePage": 58, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-1-9", "round": 114, "session": 1, "number": 9, "text": "SecureCoding", "sourcePage": 58, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-1-10", "round": 114, "session": 1, "number": 10, "text": "NOR/NANDFlashMemory", "sourcePage": 58, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-1-11", "round": 114, "session": 1, "number": 11, "text": "DRDoS(DistributedReflectionDoS)", "sourcePage": 58, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-1-12", "round": 114, "session": 1, "number": 12, "text": "5G기술성능 요구조건", "sourcePage": 58, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-1-13", "round": 114, "session": 1, "number": 13, "text": "강화학습(ReinforcementLearning) 청렴은 건전한 국가 재정의 첫걸음", "sourcePage": 58, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-2-1", "round": 114, "session": 2, "number": 1, "text": "멀티태스킹(Multitasking)을지원하는운영체제(OS)에서태스크 실행중에 인터럽트 (Interrupt)가발생하였다.태스크의실행을 중단하고 ISR(InterruptServiceRoutine)이 수행되기까지 과정과 ISR수행이 끝난 후 태스크가 다시 실행되는 과정을 레지스터 (Register)와스택(Stack)을이용하여설명하시오.", "sourcePage": 59, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-2-2", "round": 114, "session": 2, "number": 2, "text": "클라우드 환경에서 기존 보안기술을 가상화 환경에 적용했을 때 한계점을 기술하고, 하이퍼바이저(Hypervisor)기반의가상화 침입 대응기술에 대하여 설명하시오.", "sourcePage": 59, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-2-3", "round": 114, "session": 2, "number": 3, "text": "아웃소싱에 의해 IT서비스를 제공받고 있는 기업에서 서비스 업무를 제고하기 위한 방안으로 ITSM(ITServiceManagement)을구축하고자한다.검토될수있는 모델의 특징을 기술하고,ITSM을 성공적으로 구축하기 위한 요건들을 설명하시오.", "sourcePage": 59, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-2-4", "round": 114, "session": 2, "number": 4, "text": "최근금융기관에서 발생된 사고가 복잡해지고 대형화되고 있다.본인인증 및 부정사용방지, 정보저장 측면에서의 해결방안에 대하여 설명하시오.", "sourcePage": 59, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-2-5", "round": 114, "session": 2, "number": 5, "text": "저출산및 노동시간 단축에 대한 해결방안으로 추진되고 있는 스마트워크(SmartWork)의 요소기술 및 발전방향에 대하여 설명하시오.", "sourcePage": 59, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-2-6", "round": 114, "session": 2, "number": 6, "text": "차세대 이동통신에 적용된 네트워크 슬라이싱(NetworkSlicing)에대하여설명하시오. 청렴은 건전한 국가 재정의 첫걸음", "sourcePage": 59, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-3-1", "round": 114, "session": 3, "number": 1, "text": "CPU의효율성을 개선하기 위한 동시 멀티스레딩(SimultaneousMultithreading,또는 Hyperthreading)기술과그한계점을설명하시오.", "sourcePage": 60, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-3-2", "round": 114, "session": 3, "number": 2, "text": "차세대네트워크 기술로 부각되고 있는SDN(SoftwareDefinedNetworking)과NFV(Network FunctionVirtualization)의구조와특징을비교설명하시오.", "sourcePage": 60, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-3-3", "round": 114, "session": 3, "number": 3, "text": "DDoS공격유형 중에서 TCPTrafficFlooding,HTTPHead/OptionSpoofingFlooding, HashDoS공격을 각각 설명하고,그 대응방안을 기술하시오.", "sourcePage": 60, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-3-4", "round": 114, "session": 3, "number": 4, "text": "사람과 사물,사물과 사물간의 정보를 상호 소통하게 하는 지능형 사물인터넷 구현을 위한 필요기술과 구현방식,향후 발전방향에 대하여 설명하시오.", "sourcePage": 60, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-3-5", "round": 114, "session": 3, "number": 5, "text": "대용량,고속 데이터 처리를 위한 네트워크 스토리지 구성방법과 각각의 특성에 대하여 기술하고,스토리지 구축 시 고려사항을 설명하시오.", "sourcePage": 60, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-3-6", "round": 114, "session": 3, "number": 6, "text": "최근 데이터 트래픽 증가로 인해 이슈가 되고 있는 망 중립성에 대해 찬성 측과 반대 측의 논리를 기술하고,향후 전망에 대하여 설명하시오. 청렴은 건전한 국가 재정의 첫걸음", "sourcePage": 60, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-4-1", "round": 114, "session": 4, "number": 1, "text": "캐시(Cache)메모리에서주소맵핑(Mapping)방식과교체알고리즘(Replacementalgorithm)을 설명하시오.", "sourcePage": 61, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-4-2", "round": 114, "session": 4, "number": 2, "text": "RM(RateMonotonic)스케줄링알고리즘을 설명하고,다음 3개의 태스크(Task)를 스케줄링 하시오. (단,시간:0∼20,각 태스크들은 매 주기마다 릴리즈 (Release)된다고가정한다). 태스크(task)실행시간(ex ecutiontime) 주기(period) P1 1 8 P2 2 5 P3 4 10", "sourcePage": 61, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-4-3", "round": 114, "session": 4, "number": 3, "text": "미래 핵심기술로 주목 받고 있는 블록체인(BlockChain)의유형과산업별 적용분야 및 문 제점,해결방안에 대하여 설명하시오.", "sourcePage": 61, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-4-4", "round": 114, "session": 4, "number": 4, "text": "정보공학방법론 으로 개발되어 운영 중인 시스템 을 CBD(ComponentBasedDevelopment) 방법론 으로 적용하여 개발하고자 한다.CBD방법론 의 요소기술 및 개발공정,개발과정에서 발생될 수 있는 문 제점과 해결방안에 대하여 설명하시오.", "sourcePage": 61, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-4-5", "round": 114, "session": 4, "number": 5, "text": "대규모로 운영 중인 시스템 을 개편하기 위해 PMO와 감리가 참여하는 프로젝트를 추진 하고자 한다.개발단계에서의 PMO와 감리간의 역할,PMO한계점 및 해결방안에 대하여 설명하시오.", "sourcePage": 61, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "114-4-6", "round": 114, "session": 4, "number": 6, "text": "유무선 통신망을 활용한 차량 통신기술인 V2X(VehicletoEverything)의종류와통신 표준 에 대하여 설명하시오. 청렴은 건전한 국가 재정의 첫걸음", "sourcePage": 61, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-1-1", "round": 116, "session": 1, "number": 1, "text": "알고리즘의 시간복잡도 (TimeComplexity)O(1),O(n),O(n)에대하여설명하시오.", "sourcePage": 62, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-1-2", "round": 116, "session": 1, "number": 2, "text": "PCB(ProcessControlBlock)", "sourcePage": 62, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-1-3", "round": 116, "session": 1, "number": 3, "text": "플렌옵틱 영상처리 (PlenopticImageProcessing)", "sourcePage": 62, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-1-4", "round": 116, "session": 1, "number": 4, "text": "워터링홀 (WateringHole)공격", "sourcePage": 62, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-1-5", "round": 116, "session": 1, "number": 5, "text": "ISO26262", "sourcePage": 62, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-1-6", "round": 116, "session": 1, "number": 6, "text": "IDX(IntelligentDigitalX-formation)", "sourcePage": 62, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-1-7", "round": 116, "session": 1, "number": 7, "text": "SAN(StorageAreaNetwork)", "sourcePage": 62, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-1-8", "round": 116, "session": 1, "number": 8, "text": "SCTP(StreamControlTransmissionProtocol)", "sourcePage": 62, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-1-9", "round": 116, "session": 1, "number": 9, "text": "제품 백로그 (ProductBacklog)", "sourcePage": 62, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-1-10", "round": 116, "session": 1, "number": 10, "text": "DHCP(DynamicHostConfigurationProtocol)IP주소할당과정", "sourcePage": 62, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-1-11", "round": 116, "session": 1, "number": 11, "text": "운영체제에서 Process의5가지 상태(State)에대해서 설명하시오 .", "sourcePage": 62, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-1-12", "round": 116, "session": 1, "number": 12, "text": "분할 정복(DivideandConquer),탐욕법(Greedy),동적계획법(DynamicProgramming)에 대하여 설명하시오.", "sourcePage": 62, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-1-13", "round": 116, "session": 1, "number": 13, "text": "중앙처리장치의 메이저 상태(MajorState)4가지를 설명하시오.", "sourcePage": 62, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-2-1", "round": 116, "session": 2, "number": 1, "text": "최근금융,교통,의료 등 다양한 분야에 IoT기술이 적용되고 있고,빅데이터 스트림이 대규모로 발생하고 있다.빅데이터 스트림을 정확하고 빠르게 분석/처리하기 위해서는 효율적인 샘플링과 필터링 기법이 필요하다. 가.샘플링 기법 중 랜덤샘플링에 대하여 설명하시오. 나.필터링(학습기반,비학습기반) 기법에 대하여 설명하시오.", "sourcePage": 63, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-2-2", "round": 116, "session": 2, "number": 2, "text": "OSI7계층 프로토콜에 대하여 각 계층별 기능 및 역할,관련 국제표준,관련 장비 등을 중심으로 설명하시오.", "sourcePage": 63, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-2-3", "round": 116, "session": 2, "number": 3, "text": "위치정보를 무선통신에 활용하는 방안에 대하여 설명하시오.", "sourcePage": 63, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-2-4", "round": 116, "session": 2, "number": 4, "text": "ARP(AddressResolutionProtocol)에대하여아래사항들을설명하시오. 가.ARP와 RARP 나.IP프로토콜을 사용하는 서버 또는 네트워크 장비에서 ARP의 역할 다.ARP와 관련된 아래의 보안 취약점 및이들의 대응 방안 1)ARPSpoofing 2)ARPRedirect", "sourcePage": 63, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-2-5", "round": 116, "session": 2, "number": 5, "text": "데이터베이스 트랜잭션과 관련하여 아래 사항을 설명하시오 . 가.데이터베이스 트랜잭션의 개념 및 특징 4가지 나.트랜잭션 상태전이도 및 각각의 상태 다.트랜잭션들이 동시에 수행될 때 발생가능한 문제점들과 해결기법", "sourcePage": 64, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-2-6", "round": 116, "session": 2, "number": 6, "text": "전자정부 성과관리 지침에 따른 정보시스템 운영 성과관리에 대하여 아래 사항을 설명하시오 . 가.성과측정 지표 나.성과측정 절차 다.개선방안 마련 절차", "sourcePage": 64, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-3-1", "round": 116, "session": 3, "number": 1, "text": "L4스위치에 대하여 아래 사항을 설명하시오 . 가.L4 스위치 SLB(ServerLoadBalancer)동작방식 나.L4 스위치 서버 상태 감시 방식 다.L4 스위치 장애 사례와 대응방안", "sourcePage": 65, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-3-2", "round": 116, "session": 3, "number": 2, "text": "소켓(Socket)시스템에대하여 아래 사항을 설명하시오 . 가.TCP소켓 함수(Function) 나.UDP 소켓 함수(Function)", "sourcePage": 65, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-3-3", "round": 116, "session": 3, "number": 3, "text": "기억장치 사상 입출력 (MemoryMappedI/O)방식과고립형 입출력 (IsolatedI/O) 방식에 대하여 각각 설명하고 상호 비교하시오 .", "sourcePage": 65, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-3-4", "round": 116, "session": 3, "number": 4, "text": "4차산업혁명시대의 스마트 팩토리 요소기술에 대하여 설명하시오 .", "sourcePage": 65, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-3-5", "round": 116, "session": 3, "number": 5, "text": "개인정보보호법 및 개인정보의 안전성 확보조치 기준과 관련하여 아래 사항을 설명하시오. 가.개인정보 보호법 및 그 시행령에 명시된 개인정보 보호책임자가 수행해야 할 업무 나.개인정보의 안전성 확보조치 기준에 명시된 내부관리 계획의 수립·시행과 관련하여 기술적인 관점과 관리적인 관점에서 포함되어야 할 사항", "sourcePage": 66, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-3-6", "round": 116, "session": 3, "number": 6, "text": "자율주행을 수행하기 위한 핵심기술에 대하여 설명하시오.", "sourcePage": 66, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-4-1", "round": 116, "session": 4, "number": 1, "text": "수십 명이 참여하는 대규모 IT프로젝트에 애자일 (Agile)을적용하기위해서는 효과적인 방안수립이 필요하다 .아래 사항에 대하여 설명하시오 . 가.대규모 IT프로젝트에서 발생하는 주요 문제점 나.대규모 IT프로젝트의 애자일 적용 전략 다.대규모 IT프로젝트의 애자일 적용 절차(로드맵)", "sourcePage": 67, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-4-2", "round": 116, "session": 4, "number": 2, "text": "아래그래프에서 최소신장트리(MST:MinimumSpanningTree)를구하는과정을2개의 알고리즘을 이용하여 설명하시오. 가.크루스컬(Kruskal)알고리즘 나.프림(Prim)알고리즘", "sourcePage": 67, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-4-3", "round": 116, "session": 4, "number": 3, "text": "IP주소부족문제를 해결하기 위한 IPv6에대하여 아래 사항들을 설명하시오 . 가.IPv6헤더 구조 나.패킷 단편화(fragmentation)에대해서설명하고,IPv4와IPv6에서의처리 방식 다.기존 IPv4망에서 IPv6망으로 전환하기 위한 방안", "sourcePage": 68, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-4-4", "round": 116, "session": 4, "number": 4, "text": "국내핀테크 서비스 동향에 대하여 설명하시오 .", "sourcePage": 68, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-4-5", "round": 116, "session": 4, "number": 5, "text": "GigabitWLAN기술에대하여설명하시오 .", "sourcePage": 68, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "116-4-6", "round": 116, "session": 4, "number": 6, "text": "MPEG(MovingPictureExpertsGroup)의동영상압축기법에대해서공간적인 측면과 시간적인 측면으로 나누어 설명하시오 .", "sourcePage": 68, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-1-1", "round": 117, "session": 1, "number": 1, "text": "규제 샌드박스(sandbox)", "sourcePage": 69, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-1-2", "round": 117, "session": 1, "number": 2, "text": "양자정보통신에서 양자(Quantum)의특성", "sourcePage": 69, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-1-3", "round": 117, "session": 1, "number": 3, "text": "스마트 도시의 복원력(Resilience)", "sourcePage": 69, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-1-4", "round": 117, "session": 1, "number": 4, "text": "연동기획(RollingWavePlanning)", "sourcePage": 69, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-1-5", "round": 117, "session": 1, "number": 5, "text": "네트워크 전송계층(TransportLayer)역할", "sourcePage": 69, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-1-6", "round": 117, "session": 1, "number": 6, "text": "유니커널(Unikernel)기반의클라우드 운영체제", "sourcePage": 69, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-1-7", "round": 117, "session": 1, "number": 7, "text": "Wi-SUN(WirelessSmartUtilityNetwork)프로토콜", "sourcePage": 69, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-1-8", "round": 117, "session": 1, "number": 8, "text": "ISO14971", "sourcePage": 69, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-1-9", "round": 117, "session": 1, "number": 9, "text": "요구명세(SoftwareRequirementSpecification)", "sourcePage": 69, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-1-10", "round": 117, "session": 1, "number": 10, "text": "RAID(RedundantArrayofInexpensiveDisks)구조", "sourcePage": 69, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-1-11", "round": 117, "session": 1, "number": 11, "text": "썬더볼트(Thunderbolt)인터페이스", "sourcePage": 69, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-1-12", "round": 117, "session": 1, "number": 12, "text": "IPsec", "sourcePage": 69, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-1-13", "round": 117, "session": 1, "number": 13, "text": "IPv6에서사용하는애니캐스트(Anycast)주소와멀티캐스트(Multicast)주소를비교/차이점", "sourcePage": 69, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-2-1", "round": 117, "session": 2, "number": 1, "text": "디자인패턴 중 팩토리 메소드 패턴(FactoryMethodPattern)을사용하는이유를설명 하고, 아래의 클래스다이어그램을 이용하여 팩토리 메소드 패턴이 적용된 자바코드 (JAVACode)를생성하시오.", "sourcePage": 70, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-2-2", "round": 117, "session": 2, "number": 2, "text": "CPU의동작을 감시하는 워치독 타이머(WatchdogTimer)에대하여기술하고하드웨어 구현방법을 설명하시오.", "sourcePage": 70, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-2-3", "round": 117, "session": 2, "number": 3, "text": "AI(ArtificialIntelligence)기술발전에따른금융생태계변화를설명하시오.", "sourcePage": 70, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-2-4", "round": 117, "session": 2, "number": 4, "text": "4차산업혁신을 위한 신뢰성 있는 통신의 중요성에 대하여 ISO19626을활용하여 설명 하시오.", "sourcePage": 71, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-2-5", "round": 117, "session": 2, "number": 5, "text": "Multiplexing과MultipleAccess의차이점을설명하시오.", "sourcePage": 71, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-2-6", "round": 117, "session": 2, "number": 6, "text": "메시지인증 기법과 디지털 서명 기법에 대하여 설명하고 공통점과 차이점에 대하여 설명하시오.", "sourcePage": 71, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-3-1", "round": 117, "session": 3, "number": 1, "text": "조달청은 공공소프트웨어 사업 유형에 맞는 제안서 평가기준 마련을 위해 '조달청 협상에 의한 계약 제안서평가 세부기준'을 개정,2019년2월부터 시행하기로 하였다. 기존에 단일 기준으로 평가하였던 소프트웨어 사업을 유형에 맞게 다양화하여 평가하는 배경과 변경된 사업 유형의 주요 내용을 설명하고, 각 사업 유형별로 효율적인 제안서 작성 방안을 기술하시오.", "sourcePage": 72, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-3-2", "round": 117, "session": 3, "number": 2, "text": "블록체인(Blockchain)의개념을분산원장기술(DistributedLedgerTechnology)과비교 하여 설명하고 블록체인의 세부 기술요소와 국내외 서비스동향을 설명하시오. 그리고 이 분야에서 우리나라가 국제 기술 경쟁력을 확보할 수 있는 방안에 대하여 설명하시오.", "sourcePage": 72, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-3-3", "round": 117, "session": 3, "number": 3, "text": "전자정부의 챗봇(ChatBot)활용에대하여 설명하시오.", "sourcePage": 72, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-3-4", "round": 117, "session": 3, "number": 4, "text": "방송통신설비의 기술기준에 대하여 설명하시오.", "sourcePage": 72, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-3-5", "round": 117, "session": 3, "number": 5, "text": "IP터널링기술에 대하여 설명하시오.", "sourcePage": 72, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-3-6", "round": 117, "session": 3, "number": 6, "text": "SSL(SecureSocketsLayer)프로토콜에대하여설명하시오.", "sourcePage": 72, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-4-1", "round": 117, "session": 4, "number": 1, "text": "2018년5월25일부터시행된 EU(유럽연합)의 개인정보보호 법령인 개인정보보호규정 (GDPR:GeneralDataProtectionRegulation)에대해우리기업도대응해야할필요성이 있다. 아래 사항에 대하여 설명하시오. 가.2018년5월에시행된 GDPR관련 주요 변경 사항 나.GDPR의주요 골자 다.EUGDPR과 한국 개인정보보호법 비교 라.우리기업의 준비사항", "sourcePage": 73, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-4-2", "round": 117, "session": 4, "number": 2, "text": "프로젝트 관리 요소 중 위험관 리 영역에 대하여 설명하시오. 가.위험관 리와 이슈관 리를 비교 나.Boehm의10대위험 목 록(자주 발생하는 위험 요소) 다.프로젝 트에서 위험 과 이슈 의 통합관 리 방안", "sourcePage": 73, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-4-3", "round": 117, "session": 4, "number": 3, "text": "스마트공장 성공을 위한 소프트웨어의 역할과 과제에 대하여 설명하시오.", "sourcePage": 73, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-4-4", "round": 117, "session": 4, "number": 4, "text": "의료기기 분야의 국내 중소기업이 관련 소프트웨어의 안전성과 유효성을 확보한 제품 을 개발 할 수 있는 방안에 대하여 아래 2가지 사항을 중심 으로 설명하시오. 가.의료 기기 소프트웨어 관 련 표준 나.의료 기기 소프트웨어 품질관 리시스템", "sourcePage": 74, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-4-5", "round": 117, "session": 4, "number": 5, "text": "VR(VirtualReality)미디어획득을위해아래 사항들 을 설명하시오. 가.3-DoF(DegreesofFreedom)지원VR미디어획득 나.6-DoF(DegreesofFreedom)지원VR미디어획득", "sourcePage": 74, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "117-4-6", "round": 117, "session": 4, "number": 6, "text": "4G/5G네트워크의 핵심 기술을 설명하시오.", "sourcePage": 74, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-1-1", "round": 119, "session": 1, "number": 1, "text": "SVM(SupportVectorMachine)", "sourcePage": 75, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-1-2", "round": 119, "session": 1, "number": 2, "text": "인공신경망의 오류 역전파 (Backpropagation)알고리즘", "sourcePage": 75, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-1-3", "round": 119, "session": 1, "number": 3, "text": "오버라이딩 (Overriding)으로함수를재정의 하는 이유", "sourcePage": 75, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-1-4", "round": 119, "session": 1, "number": 4, "text": "HTTP 3.0", "sourcePage": 75, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-1-5", "round": 119, "session": 1, "number": 5, "text": "BibaIntegrityModel", "sourcePage": 75, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-1-6", "round": 119, "session": 1, "number": 6, "text": "모니터 (Monitor)프로세스동기화 기법", "sourcePage": 75, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-1-7", "round": 119, "session": 1, "number": 7, "text": "Ad-hocNetworkRoutingProtocol", "sourcePage": 75, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-1-8", "round": 119, "session": 1, "number": 8, "text": "OAuth2.0", "sourcePage": 75, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-1-9", "round": 119, "session": 1, "number": 9, "text": "포그 컴퓨팅 (FogComputing)", "sourcePage": 75, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-1-10", "round": 119, "session": 1, "number": 10, "text": "어플라이언스 (Appliance)서버", "sourcePage": 75, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-1-11", "round": 119, "session": 1, "number": 11, "text": "FeRAM/STT-MRAM/PRAM", "sourcePage": 75, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-1-12", "round": 119, "session": 1, "number": 12, "text": "SCSIRDMA(RemoteDirectMemoryAccess)", "sourcePage": 75, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-1-13", "round": 119, "session": 1, "number": 13, "text": "WAF(WebApplicationFirewall)", "sourcePage": 75, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-2-1", "round": 119, "session": 2, "number": 1, "text": "OpenStack의특징과 구성도 및 서비스에 대하여 설명하시오 .", "sourcePage": 76, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-2-2", "round": 119, "session": 2, "number": 2, "text": "VPN(VirtualPrivateNetwork)을구현방식과 서비스 형태에 따라 비교하여 설명하고 , SSL VPN방식에 대하여 설명하시오 .", "sourcePage": 76, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-2-3", "round": 119, "session": 2, "number": 3, "text": "4차 산업혁명을 주도하고 있는 인공지능 머신러닝 기술은 실제로 적대적 공격 (AdversarialAttack)에취약한것으로 알려져 있다 .다음에 대하여 설명하시오 . 1)자율주행자동차에 대한 적대적 공격 2)적대적 공격을 위한 적대적 샘플 (AdversarialSample)제작기법 3)적대적 공격에 대한 방어기법", "sourcePage": 76, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-2-4", "round": 119, "session": 2, "number": 4, "text": "DNS를 은닉채널 (CovertChannel)로사용하는 이유를 설명하고 ,DNS CovertChannel 공격모델 및 방어기법을 설명하시오 .", "sourcePage": 77, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-2-5", "round": 119, "session": 2, "number": 5, "text": "TTA 기반으로 정보시스템의 H/W용량을 산정하고자 한다 .다음에 대하여 설명하시오 . 1)H/W규모산정 방법에 대한 개념 및 장 ·단점 2)규모산정 대상 3)CPU및 스토리지의 성능 기준치", "sourcePage": 77, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-2-6", "round": 119, "session": 2, "number": 6, "text": "클라우드 시스템 구축을 위한 핵심 기술인 가상화 관련 기술 중 가상머신과 컨테이너를 비교하여 설명하시오 .", "sourcePage": 77, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-3-1", "round": 119, "session": 3, "number": 1, "text": "피보나치 수 Fn은 다음과 같은 규칙으로 정의된다 .F0=0,F1=1,...,Fn=Fn-1+Fn-2. 피보나치 수를 재귀함수를 이용하여 의사코드 (PseudoCode)또는 임의의 프로그래밍 언어로 구현하고 ,재귀함수보다 효율적으로 동작시키기 위한 기법을 제시하시오 .", "sourcePage": 78, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-3-2", "round": 119, "session": 3, "number": 2, "text": "IPv6의 ND(NeighborDiscovery)의기능과 ND와 관련된 ICMPv6메시지에 대하여 설명하시오 .", "sourcePage": 78, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-3-3", "round": 119, "session": 3, "number": 3, "text": "국가기반시설을 원격에서 감시 및 제어하는 SCADA(SupervisoryControlAnd Data Acquisition)시스템의 내부구조를 설명하고 ,SCADA 공격용 프로그램인 Stuxnet의 동작과정 및 대응방안을 설명하시오 .", "sourcePage": 78, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-3-4", "round": 119, "session": 3, "number": 4, "text": "정보시스템감리 과업이행여부 점검 시 표본조사가 원칙이나 현실적으로는 발주기관에서 전수조사를 원칙으로 요구하는 사례가 많은 실정이다 .다음에 대하여 설명하시오 . 1)과업이행여부 전수점검에 대한 현실적 한계성과 감리에 미치는 문제점 2)과업이행여부 전수점검에 대한 개선방안인 문서검토확인과 제 3자 검증 방법", "sourcePage": 78, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-3-5", "round": 119, "session": 3, "number": 5, "text": "대용량의 데이터 처리가 산업전반에 걸쳐 상용화되고 있다 .대용량 데이터의 처리 및 검색 성능을 고려하여 데이터베이스를 파티션을 통해 분산 및 저장하는 것을 검토하고 있다 .다음에 대하여 설명하시오 . 1)파티셔닝을 추진하는 목적 2)파티셔닝 종류 3)분할 기준", "sourcePage": 79, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-3-6", "round": 119, "session": 3, "number": 6, "text": "최근 차세대 시스템을 추진하는 금융기업에서는 개발자 확보 및 모델 중심의 개발을 목적으로 MDD(ModelDrivenDevelopment)도입을 적 극 검토하고 있다 .다음에 대하여 설명하시오 . 1)개발방법 론 특징 비교 (구조적 방법 론, 객체지 향 방법 론, CBD,MDD) 2)MDD 개념 및 특징 3)MDD 개발 참여자의 역할 4)MDD 유용성과 제약사 항", "sourcePage": 79, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-4-1", "round": 119, "session": 4, "number": 1, "text": "SDN아키 텍처와 Openflow에대하여 설명하시오 .", "sourcePage": 80, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-4-2", "round": 119, "session": 4, "number": 2, "text": "빅데이터 시스템 구축 및 활용을 위한 기술 들을 설명하시오 .", "sourcePage": 80, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-4-3", "round": 119, "session": 4, "number": 3, "text": "딥러닝 (DeepLearning)가중치학습을 위한 경사하 강법 (GradientDescent)에대하여 다음을 설명하시오 . 1)경사하 강법의 개념 2)경사하 강법에서 오버 슈팅 (Overshooting)을방지하는방법 3)경사하 강법에서 지역 최 소점 (LocalMinimum)에빠지지 않고 본래의 최 소점에 도 달하기 위한 기법", "sourcePage": 80, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-4-4", "round": 119, "session": 4, "number": 4, "text": "개발단계 소프 트웨어의 소스코드 품질평가 및 신 뢰도 측정방법에 대하여 설명하시오 .", "sourcePage": 80, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-4-5", "round": 119, "session": 4, "number": 5, "text": "데이터가 국가 미래 산업의 핵심 성장 동력으로 평가 받고 있다 .데이터 시장의 활성화를 위하여 오픈 데이터 플 랫폼을 적극 검토하고 있다 .다음에 대하여 설명하시오 . 1)데이터의 생명주기 2)문서의 개방방식 3)LOD(LinkedOpenData)의기술요 소", "sourcePage": 81, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "119-4-6", "round": 119, "session": 4, "number": 6, "text": "금융 산업에서는 고성능의 트랜잭션 처리를 필요로 하고 있다 .초고 속 트랜잭션 처리를 위해 In-MemoryComputing기술을 도입하고자 한다 .다음에 대하여 설명하시오 . 1)In-MemoryComputing의등장 배경 2)In-MemoryComputing기술", "sourcePage": 81, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-1-1", "round": 120, "session": 1, "number": 1, "text": "프리크라임 (Pre-Crime)시스템", "sourcePage": 82, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-1-2", "round": 120, "session": 1, "number": 2, "text": "순환 신경망 (RecurrentNeuralNetwork:RNN)", "sourcePage": 82, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-1-3", "round": 120, "session": 1, "number": 3, "text": "국가재난안전통신망 (PS-LTE)과철도전용무선통신망 (LTE-R),초고속해상무선통신망 (LTE-M)을 설명하시오 .", "sourcePage": 82, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-1-4", "round": 120, "session": 1, "number": 4, "text": "ISO 20547", "sourcePage": 82, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-1-5", "round": 120, "session": 1, "number": 5, "text": "GPU(GraphicsProcessingUnit)", "sourcePage": 82, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-1-6", "round": 120, "session": 1, "number": 6, "text": "네트워크 운영 체제 (NetworkOperatingSystem:NOS)", "sourcePage": 82, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-1-7", "round": 120, "session": 1, "number": 7, "text": "원격 프로시저 호출 (RemoteProcedureCall:RPC)", "sourcePage": 82, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-1-8", "round": 120, "session": 1, "number": 8, "text": "대역확산 (SpreadSpectrum)", "sourcePage": 82, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-1-9", "round": 120, "session": 1, "number": 9, "text": "레터럴 무브먼트 (LateralMovement)", "sourcePage": 82, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-1-10", "round": 120, "session": 1, "number": 10, "text": "CAM(Content-AddressableMemory)에대하여일반적인메모리와 비교하여 설명하시오 . (기본개념 ,액세스 방법 및 활용분야 )", "sourcePage": 82, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-1-11", "round": 120, "session": 1, "number": 11, "text": "마이크로서비스 아키텍쳐 (Micro-serviceArchitecture)", "sourcePage": 82, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-1-12", "round": 120, "session": 1, "number": 12, "text": "세마포어 (Semaphore)와뮤텍스 (Mutex)를 비교 설명하시오 .", "sourcePage": 82, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-1-13", "round": 120, "session": 1, "number": 13, "text": "RTLS(Real-TimeLocatingSystem)", "sourcePage": 82, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-2-1", "round": 120, "session": 2, "number": 1, "text": "머신러닝 알고리즘 중 선형 회귀 (LinearRegression)와 로지스틱 회귀 (Logistic Regression)에 대하여 설명하고 아래 표를 참고하여 다음을 설명하시오 . X Y 1 1 2 2 3 3 가 .가설과 비용함수를 설정하시오 . 나 .가중치 (Weight)변화에 따른 비용 간 그래프를 도식화 하시오 . 다 .가설과 비용함수를 통해 비용이 최소화되는 가중치를 구하시오 .", "sourcePage": 83, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-2-2", "round": 120, "session": 2, "number": 2, "text": "최 근 정부는 공공기관이 보유 및 관리하는 데이터의 제공 및 그 이용활성화에 관한 사항을 규정함으로써 국민의 공공데이터에 대한 이용권을 보장하고 궁극적으로 국민경제 발 전에 이바지하기 위해 공공데이터제공 정책을 펼치고 있다 .이에 대하여 다음 사항을 설명하시오 . 가 .공공데이터의 정의 및 포맷별 유형 나 .공공데이터 제공과 공개의 차이점", "sourcePage": 83, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-2-3", "round": 120, "session": 2, "number": 3, "text": "회사의 네트워크 시스템을 내부망과 외부망으로 분리하여 운영하고자 한다 . 망분리 용역발주 시 필요한 기술사양서 (TechnicalSpecification)에포함하여야 할 목차 (TableofContents)를설명하시오 .", "sourcePage": 84, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-2-4", "round": 120, "session": 2, "number": 4, "text": "SCADA(SupervisoryControlandDataAcquisition)시스템의 구성요소 ,감시 (Monitoring)와제어 (Control)의차이점을 설명하시오 .", "sourcePage": 84, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-2-5", "round": 120, "session": 2, "number": 5, "text": "인터럽트 (Interrupt)에대하여 다음사항을 설명하시오 . 가 .인터럽트 발생 요인 (하드웨어 및 소프트웨어 ) 나 .마스커블 (Maskable)인터럽트와 넌마스커블 (Non-maskable)인터럽트 다 .벡터 (Vectored)인터럽트의 동작원리 라 .우 선순위 (Priority)를보장하는 다중 (Multiple)인터럽트가 발생한 경우 이를 처리하기 위 한 ISR(InterruptServiceRoutine)을프로세서 및 소프트웨어에서 제공하여야 하는 기능요소들과 상호 연관시켜 설명하시오 .", "sourcePage": 84, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-2-6", "round": 120, "session": 2, "number": 6, "text": "디지털 트윈 (DigitalTwin)에대하여 다음 사항들을 설명하시오 . 가 .디지털 트윈의 정의와 출현배경 나 .디지털 트윈과 M&S(Modeling& Simulation)의연관성 다 .디지털 트윈의 산업분야 적용 라 .디지털 트윈 운영환경 (소프트웨어 측 면의 구성요소 ,산업분야 운용을 위한 HW 및 시스템 SW 인프라 )", "sourcePage": 85, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-3-1", "round": 120, "session": 3, "number": 1, "text": "TCP(TransmissionControlProtocol)의신뢰성있는 전 송을 가능 케 하는 오 류제어 , 흐름제어 ,혼잡제어에 대하여 설명하시오 .", "sourcePage": 86, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-3-2", "round": 120, "session": 3, "number": 2, "text": "모바일 및 임베디드 시스템에 주로 이용되고 있는 ARM(AdvancedRISCMachine) 프로세서에 대하여 다음 사항을 설명하시오 . 가 .ARM 프로세서의 특징 나 .ARM 하드웨어 임 베디드 시스템 아키텍처 다 .ARM 소프트웨어 계층 구조", "sourcePage": 86, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-3-3", "round": 120, "session": 3, "number": 3, "text": "기능안전 (FunctionalSafety)분야에서사용하는 정보통신망의 적 합성을 평가하고자 한다 . 이에 필요한 기술 평가 항목들 (TechnicalEvaluationItems)과체크리스트를작성하시오 .", "sourcePage": 86, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-3-4", "round": 120, "session": 3, "number": 4, "text": "머신러닝 (MachineLearning)의학습방법 은 크 게 3가지 [지도 학습(SupervisedLearning), 비지도 학습(UnsupervisedLearning),강화학습(ReinforcementLearning)]로분류한다. 인공지능 소프트웨어 개발 프로세스를 V모 델 기준으로 도식화하고 관련기술의 최신 동향 및 안전 취약성을 설명하시오 .", "sourcePage": 86, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-3-5", "round": 120, "session": 3, "number": 5, "text": "제 4차 산업 혁명과 관 련한 스마트 팩토리에 대하여 다음 사항을 설명하시오 . 가 . 국내 스마트 팩토리 확산을 위한 정책과 대 응방안으로 국내 민관 합동 스마트 팩토리 추진단 은 한국형 스마트 팩토리를 IT기술과 자동화 기술을 최대한 활용해 글로 벌 경 쟁력을 갖추는 것으로 정의하 였다 .이러한 정의에 의한 국내 스마트 팩토리의 수준을 고 도화 ,중간수준 2,중간수준 1,기초수준 ,ICT미적용 등 5단계에 대하여 설명하고 ,각 수준별 공 장자동화 ,공장운영 ,기업자원 관리 ,제품개발 ,공 급사 슬 관리에 대하여 설명하시오 . 나 . 스 마트 팩토리를 위한 요소기술 은 반드시 적용해야 하는 새로운 개념의 기술이 언제 든지 등장할 수 있어서 시대의 흐름에 따라 바 뀔 수 있다 .현재시점에서 스마트 팩토리를 구성하기 위하여 요구되는 요소기술을 나 열하고 설명하시오 .", "sourcePage": 87, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-3-6", "round": 120, "session": 3, "number": 6, "text": "마이크로 컴퓨터에서 PWM(PulseWidthModulation)을 발생시키고자 할 때,다음과 같은 사항을 참 조하여 설명하시오 . 가 . 마 이크로 컴퓨터에는 다음과 같은 종류의 레지스터를 포함하고 있다 .즉,0으로부터 count-up을 반 복하는 8비트의 Read/Write가능한 “카운터레지스터 (CounterRegister)”와 카운터 레지스터 값과 비교하기 위한 값을 저장하는 8비트의 “출 력비교레지스터 (Output CompareRegister)”가있고,카운터 레지스터의 값이 출 력비교레지스터에 저장 된 값과 같을 때 비 교출 력신호의 상태를 변화시 킨다 .마이크로 컴퓨터의 CPU클럭주 파수 f=16MHz로 하고 , 이를 64분주하여 카운터레지스터의 카운 팅 기준시간으로 적용한다 .이러한 상 황을 이 용하여 ,마이크로 컴퓨터에서 PWM 을 발생시 킬 수 있는 원리를 개념적으로 설명하시오 . 나. “가”항의 원리를 이용하여 ,PWM 의 dutycycle을고속 (90%),중속 (70%),저속 (50%)등으로 조절하여 모터의 속도제어나 조명의 디밍(dimming)제어가가능함을 계산을 통하여 설명하시오 . (단,문제에서 주어지지 않은 조건은 임의로 정의 가능 )", "sourcePage": 87, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-4-1", "round": 120, "session": 4, "number": 1, "text": "병렬처리를 위한 컴퓨터구 조설계기법으로 분기 예측 기술의 2가지 방법인 분기방 향 예측과 분기목적지 예측에 대해 설명하고 예측 실행(SpeculativeExecution)기술에 대하여 설명하시오 .", "sourcePage": 89, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-4-2", "round": 120, "session": 4, "number": 2, "text": "ISO7498이 필요한 이유와 각 계층별 역할 및 기능 ,취급하는 자 료 형 태와 관 련 장비에 대하여 설명하시오 .", "sourcePage": 89, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-4-3", "round": 120, "session": 4, "number": 3, "text": "회사 내 사이 버보안 조직의 역할 및 책임사항을 평상시와 비상시로 구분하여 설명하시오 .", "sourcePage": 89, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-4-4", "round": 120, "session": 4, "number": 4, "text": "기능안전 분야 (국방 ,우주 /항공 ,철도 ,선 박,자동차 및 의 료 등)에서 능동안전 (ActiveSafety)개념을 적용하여 소형 디지털 제어기 (SmallDigitalController)를 설계하고자 한다 . 하드웨어와 소프트웨어 관점에서 안전설계 개념 (SafetyDesign Concept)과안전메 카니즘 (SafetyMechanism)을 설명하시오 .", "sourcePage": 89, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-4-5", "round": 120, "session": 4, "number": 5, "text": "포그 컴퓨팅(FogComputing)을 설명하고 ,엣지 컴퓨팅(EdgeComputing)및 클라우드 컴퓨팅(CloudComputing)과 비교하여 설명하시오 .", "sourcePage": 89, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "120-4-6", "round": 120, "session": 4, "number": 6, "text": "교환방식에 있어서 회선교환 (CircuitSwitching)방식과패킷교환 (PacketSwitching)방식에 대하여 설명하고 ,음성데이터나 영상데이터와 같은 실시간 트래 픽 서비스를 패킷교환방식의 네트워크에서 제공하고자할 때 발생할 수 있는 문제점 및 해결방안에 대하여 설명하시오 .", "sourcePage": 89, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-1-1", "round": 122, "session": 1, "number": 1, "text": "전가산기 (FullAdder)", "sourcePage": 90, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-1-2", "round": 122, "session": 1, "number": 2, "text": "RAID(RedundantArrayofInexpensiveDisks)", "sourcePage": 90, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-1-3", "round": 122, "session": 1, "number": 3, "text": "모바일 엣지 컴퓨팅 (MobileEdgeComputing)", "sourcePage": 90, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-1-4", "round": 122, "session": 1, "number": 4, "text": "해밍거리 (HammingDistance)", "sourcePage": 90, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-1-5", "round": 122, "session": 1, "number": 5, "text": "IMDG(In-MemoryDataGrid)", "sourcePage": 90, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-1-6", "round": 122, "session": 1, "number": 6, "text": "GraphDB", "sourcePage": 90, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-1-7", "round": 122, "session": 1, "number": 7, "text": "Scale-Up/Scale-Out", "sourcePage": 90, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-1-8", "round": 122, "session": 1, "number": 8, "text": "GPU(GraphicProcessingUnit)와CPU(CentralProcessingUnit)차이점", "sourcePage": 90, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-1-9", "round": 122, "session": 1, "number": 9, "text": "백트래킹 (Backtracking),분할정복,탐욕법,동적계획법의 개념 및 알고리즘 사례", "sourcePage": 90, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-1-10", "round": 122, "session": 1, "number": 10, "text": "인공지능 데이터의 평가를 위한 고려사항", "sourcePage": 90, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-1-11", "round": 122, "session": 1, "number": 11, "text": "제로 트러스트 (ZeroTrust)보안모델", "sourcePage": 90, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-1-12", "round": 122, "session": 1, "number": 12, "text": "생성적 적대 신경망 (GenerativeAdversarialNetworks:GAN)", "sourcePage": 90, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-1-13", "round": 122, "session": 1, "number": 13, "text": "기울기소실 문제 (VanishingGradientProblem)", "sourcePage": 90, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-2-1", "round": 122, "session": 2, "number": 1, "text": "자율주행의 기술동향 및 핵심기술에 대하여 설명하시오 .", "sourcePage": 91, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-2-2", "round": 122, "session": 2, "number": 2, "text": "OSI7-Layer의 데이터링크 계층에서 제공하는 서비스에 대하여 설명하시오 .", "sourcePage": 91, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-2-3", "round": 122, "session": 2, "number": 3, "text": "데 이터 웨어하우스 (DataWarehouse)와 데이터 레이크 (DataLake)의 특징을 비교하고 , 빅데이터의 요소기술과 기술영역별 표준화 대상항목을 설명하시오 .", "sourcePage": 91, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-2-4", "round": 122, "session": 2, "number": 4, "text": "최근 개정된 데이터 3법의 주요 개정내용과 개인정보 /가명정보 /익명정보의 활용 가능 범위 , 기대효과 , 후속 추진현황을 설명하시오 .", "sourcePage": 91, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-2-5", "round": 122, "session": 2, "number": 5, "text": "패션 의류용 이미지를 분류하는 다층 신경망을 만들려고 한다 .의류용 이미지는 바지 , 치 마,티셔츠 등 10가지 유형의 흑백이미지 (32*32pixels)로구성되어 있고 , 학습에 투입할 이 미지 데이터는 검증 및 테스트용 데이터를 제외하고 총 48,000장이다 .입력층 ,은닉층 , 출력층의 완전연결 (fullyconnected)3계층으로 구성되어 있고 은닉층의 뉴런 개수는 100개일 때 ,다음에 대하여 설명하시오 . 가 .신경망 구성도 나 .입력층의 입력개수 ,출력층의 뉴런개수 ,학습할 가중치와 절편의 총 개수 다 .원핫인코딩 (One-HotEncoding)과 소프트맥스 (Softmax)함수", "sourcePage": 91, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-2-6", "round": 122, "session": 2, "number": 6, "text": "인공지능 (AI)윤리의 개념 ,주요사례 ,고려사항 및 추진방향을 설명하시오 .", "sourcePage": 91, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-3-1", "round": 122, "session": 3, "number": 1, "text": "오픈소스 솔루션은 상용 소프트웨어처럼 사용료는 요구하지 않지만 ,대신 반드시 준수해야 하는 의 무조항이 있다 . 가 .오픈소스 솔루션의 의 무조항을 설명하시오 . 나 .오픈소스 솔루션과 상용 소프트웨어의 특징을 비교하여 설명하시오 .", "sourcePage": 92, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-3-2", "round": 122, "session": 3, "number": 2, "text": "4차 산 업혁명의 주요 기술로서 블록체인기술이 활용되고 있다 . 가 .블록체인 기술의 장점 ,시스 템 구축에 필요한 핵심기술을 설명하시오 . 나 .공개형과 허가형 블록체인을 비교하여 설명하시오 .", "sourcePage": 92, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-3-3", "round": 122, "session": 3, "number": 3, "text": "DNS(DomainNameSystem)가 제공하는 서비스에 대하여 설명하시오 .", "sourcePage": 92, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-3-4", "round": 122, "session": 3, "number": 4, "text": "6G 이동 통신기술에 대하여 설명하시오 .", "sourcePage": 92, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-3-5", "round": 122, "session": 3, "number": 5, "text": "머신러 닝 모델은 학습과 함께 검증 및 평가 과정이 필요하다 . 가 .교차검증 (k-foldCrossValidation)기법에 대하여 설명하시오 . 나 .머신러 닝 모델의 평가방법에 대하여 설명하시오 .", "sourcePage": 93, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-3-6", "round": 122, "session": 3, "number": 6, "text": "경사하 강법 (GradientDescent)은인공신경망 학습을 최적화하기 위한 기법이다 . 가 .평 균제 곱오차 비용함수를 가중치에 대해 편미분한 후 학습 률을 곱한 값을 기 존 가 중치에서 차 감하여 가중치 갱신을 수행한다고 가정할 때 ,가중치 최적해의 좌측 또는 우측 어 디에서 시작하 든 상 관없이 최적해를 향해 진행하는 이유를 수 식적으로 설명하시오 . 나 .확률적경사하 강법 ,배치경사하 강법 , 미니배치경사하 강법의 개념과 특징을 비교하여 설명하시오 .", "sourcePage": 93, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-4-1", "round": 122, "session": 4, "number": 1, "text": "종료 단계 감리 시 감리원은 구현기능을 직접 테스트하여 과 업이행여 부를 판정하도 록 정보시스 템감리 수행가이드에 안내되어 있다 . 가 .감리원이 직접 테스트하는 것이 현실적으로 어려 운 사례를 설명하시오 . 나 .검 토 및 확인 ,제3자검증 점검방법을 통한 개선방안을 설명하시오 .", "sourcePage": 94, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-4-2", "round": 122, "session": 4, "number": 2, "text": "정렬 알고리즘은 컴퓨터 분야에서 가장 많이 연구된 분야 중 하나이다 . 가 .선택정 렬(SelectionSort)과삽입정렬(InsertionSort),퀵정렬(QuickSort)알고리즘을 설명하시오 . 나 .다 음 키 값을 갖는 파일을 퀵정 렬(QuickSort)알고리즘을 사용하여 오름차 순으로 정 렬하려고 한다 .피벗이 50일 때 수행되는 분할과정을 단계적으로 설명하시오 . (단,n=8 :50,80,20,90,40,10,30,60)", "sourcePage": 94, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-4-3", "round": 122, "session": 4, "number": 3, "text": "UDP(UserDatagramProtocol)가제공하는 서비스를 설명하시오 .", "sourcePage": 94, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-4-4", "round": 122, "session": 4, "number": 4, "text": "정보보안의 주요한 세 가지 목적 및 각각의 목적을 위협할 수 있는 공 격방법에 대하여 설명하시오 .", "sourcePage": 95, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-4-5", "round": 122, "session": 4, "number": 5, "text": "응용시스 템 개 발과정에서 적용할 테스트 기법을 결정하는데 고려해야 할 사항과 단위 테스트를 종료하는 기준을 설명하시오 .", "sourcePage": 95, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "122-4-6", "round": 122, "session": 4, "number": 6, "text": "클라우드 컴퓨팅은 ICT를 실현하는 핵심 기술로 인식되고 있다 . 가 .클라우드 컴퓨팅의 기반기술 개념 및 요소기술을 설명하시오 . 나 .클라우드 컴퓨팅의 생태계를 설명하시오 .", "sourcePage": 95, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-1-1", "round": 123, "session": 1, "number": 1, "text": "DDR SDRAM(DoubleDataRateSynchronousDynamicRandomAccessMemory)", "sourcePage": 96, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-1-2", "round": 123, "session": 1, "number": 2, "text": "PCIExpress(PeripheralComponentInterconnectExpress)", "sourcePage": 96, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-1-3", "round": 123, "session": 1, "number": 3, "text": "동적 연결 라이브러리 (DynamicLinkingLibrary)", "sourcePage": 96, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-1-4", "round": 123, "session": 1, "number": 4, "text": "능동 학습 (ActiveLearning)", "sourcePage": 96, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-1-5", "round": 123, "session": 1, "number": 5, "text": "매니코어 프로세서 (manycoreCPU(CentralProcessingUnit))", "sourcePage": 96, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-1-6", "round": 123, "session": 1, "number": 6, "text": "MQTT(MessageQueuingTelemetryTransport)", "sourcePage": 96, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-1-7", "round": 123, "session": 1, "number": 7, "text": "Wi-Fi6E", "sourcePage": 96, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-1-8", "round": 123, "session": 1, "number": 8, "text": "산업제어시스템 (IndustrialControlSystem)의보안구조를ICT시스템과비교하여 설명하시오 .", "sourcePage": 96, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-1-9", "round": 123, "session": 1, "number": 9, "text": "지식 증류 (KnowledgeDistillation)", "sourcePage": 96, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-1-10", "round": 123, "session": 1, "number": 10, "text": "ERP(EnterpriseResourcePlanning)의POC(ProofOfConcept)", "sourcePage": 96, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-1-11", "round": 123, "session": 1, "number": 11, "text": "메모리 누수(MemoryLeak)", "sourcePage": 96, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-1-12", "round": 123, "session": 1, "number": 12, "text": "사실상 표준(defactostandard)", "sourcePage": 96, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-1-13", "round": 123, "session": 1, "number": 13, "text": "IEC61508–안전무결성 수준 (SafetyIntegrityLevel)", "sourcePage": 96, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-2-1", "round": 123, "session": 2, "number": 1, "text": "운영체제 (operatingsystem)에서발생할수 있는 클럭 인터럽트 (clockinterrupt),입출력 인터럽트 (input/outputinterrupt),페이지부재(pagefault)의경우에대하여운영체제가 하는 역할을 설명하시오 .", "sourcePage": 97, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-2-2", "round": 123, "session": 2, "number": 2, "text": "SLC(SingleLevelCell)NAND,MLC(MultiLevelCell)NAND및 TLC(Triple LevelCell)NANDFlash메모리에 관하여 다음의 내용을 설명하시오 . 가.개념 나.장단점 비교 다.응용 분야", "sourcePage": 97, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-2-3", "round": 123, "session": 2, "number": 3, "text": "5G사이버물리시스템 (Cyber-PhysicalSystems)내의통신설비,클라우드 플랫폼 인프라 기반 스마트시티 서비스 활성화 방안에 대해 4가지 모델을 고려하여 설명하시오 . 가.OBM(Open-Business-Model) 나.BOM(Build-Operate-Manage) 다.BOT(Build-Operate-Transfer) 라.BOO(Build-Own-Operate)", "sourcePage": 97, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-2-4", "round": 123, "session": 2, "number": 4, "text": "차량 긴급구난체계 (e-Call)를단말 ,관제센터 및 유관기관을 중심으로 설명하시오 .", "sourcePage": 98, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-2-5", "round": 123, "session": 2, "number": 5, "text": "A라는 회사에서 응용 소프트웨어 패키지 (applicationsoftwarepackage)를개발하였다. 시 장 (market)출시전에 SW시험 ·인증센터에 제3자 시험 ·인증을 의뢰하고자 한다 .신청부터 소프트웨어품질인증서를 받기까지의 모든 절차를 설명하시오 .", "sourcePage": 98, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-2-6", "round": 123, "session": 2, "number": 6, "text": "A라는 회사에서 특허동향분석 (patentmap)시스템을 구축하였다 . 이를 평가하기 위한 기 술평가표 (technicalevaluationsheet)를일반부분,기술부분 ,관리부분 및 지원 부분 으로 구분하여 설명하시오 .", "sourcePage": 98, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-3-1", "round": 123, "session": 3, "number": 1, "text": "캐시 일관성 (cachecoherence)이필요한 환경 및 이유를 설명하고 ,캐쉬 일관성을 유지 하기 위한 디렉토리 프로토콜 (directoryprotocol)과스누피프로토콜 (snoopyprotocol)을 비교 설명하시오 .", "sourcePage": 99, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-3-2", "round": 123, "session": 3, "number": 2, "text": "XP(eXtremeProgramming)의특징 및 실천 방법 (practice)들을설명하시오 .", "sourcePage": 99, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-3-3", "round": 123, "session": 3, "number": 3, "text": "EoS(EthernetoverSynchronousdigitalhierarchy)와이더넷링보호 절체를 비교 하여 설명하시오 .", "sourcePage": 99, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-3-4", "round": 123, "session": 3, "number": 4, "text": "초광대역 무선기술 (UltraWideBand)을이용한 거리측정방법을 설명하시오 .", "sourcePage": 99, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-3-5", "round": 123, "session": 3, "number": 5, "text": "정보통신기술 (ICT)시스템 통합 (systemintegration)시시험단계(testphase)에서반드시 거쳐야 하는 과정이 성능시험 (performancetest)이다.성능시험결과보고서에 포함하여야 할 주요목차와 내용들을 설명하시오 .", "sourcePage": 99, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-3-6", "round": 123, "session": 3, "number": 6, "text": "국제표준은 미국을 중심으로 한 IEEE-Std.Framework와유럽을 중심으로 한 IEC-Std. Framework로크게 구분할 수 있다 .이들의 주요 차이점과 특징을 간단히 비교하고 국내 ·외 정보통신기술 (ICT)표준화 동향을 설명하시오 .", "sourcePage": 99, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-4-1", "round": 123, "session": 4, "number": 1, "text": "DMA(DirectMemoryAccess)에 대하여 다음을 설명하시오 . 가 .DMA를 사용하는 이유 나 .입출력장 치에서 주기 억장 치로 정보 전 송 시 DMA를 이용한 정보전 송 다 .BurstMode,CycleStealingMode,DemandTransferMode", "sourcePage": 100, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-4-2", "round": 123, "session": 4, "number": 2, "text": "버퍼 오버플로우 (bufferoverflow)를이용한 사이버 공격을 설명하고 , 이를 해결하기 위한 소프트웨어 방안 (실 행 시간 방어 ,컴파일 시간 방어 )들을 설명하시오 .", "sourcePage": 100, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-4-3", "round": 123, "session": 4, "number": 3, "text": "물리적으로 안전한 가상 현실 서비스를 위한 주 변감지 및 경고시스템 표준 (TTAK.KO-10.1116,2018)을설명하시오 .", "sourcePage": 100, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-4-4", "round": 123, "session": 4, "number": 4, "text": "드론(Drone)서비스 관련 보안 위 협과 대응방안에 대하여 다음 각 사 항을 반영하여 설명하시오 . 가 .자산 별 보안위 협 나 .4가지 이상의 위협 시나리오", "sourcePage": 100, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-4-5", "round": 123, "session": 4, "number": 5, "text": "최근 각 분야에서 개인정보유출이 잇따르면서 경제 협력개발기구 (OECD)의 ‘프라이버시 8원칙’이 새삼 주목받고 있다 .이 8원칙은 개인정보의 수 집 및 관리에 대한 국제사회의 합의를 반영한 국제기준으로 법적인 구 속력은 없지 만 일반 원칙으로 인정받고 있다 . 경제 협력개발기구 (OECD)프라이버시 (privacy)8원칙을 설명하시오 .", "sourcePage": 100, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "123-4-6", "round": 123, "session": 4, "number": 6, "text": "공공기관의 정보기술 투자성과에 대한 성과관리를 평가체계 관점에서 설명하시오 .", "sourcePage": 100, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-1-1", "round": 125, "session": 1, "number": 1, "text": "IEEE802.11ax와IEEE802.11be비교", "sourcePage": 101, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-1-2", "round": 125, "session": 1, "number": 2, "text": "엣지 컴퓨팅 (EdgeComputing)", "sourcePage": 101, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-1-3", "round": 125, "session": 1, "number": 3, "text": "UNIX시스템의 3가지 핵심 컴포넌트 (Component)", "sourcePage": 101, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-1-4", "round": 125, "session": 1, "number": 4, "text": "DRAM(DynamicRAM)과 SRAM(StaticRAM)", "sourcePage": 101, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-1-5", "round": 125, "session": 1, "number": 5, "text": "Shellcode", "sourcePage": 101, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-1-6", "round": 125, "session": 1, "number": 6, "text": "RAID0+1과 RAID1+0", "sourcePage": 101, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-1-7", "round": 125, "session": 1, "number": 7, "text": "LiDAR(LightDetectionandRanging)와RADAR(RadioDetectionandRanging)", "sourcePage": 101, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-1-8", "round": 125, "session": 1, "number": 8, "text": "안티드론 (Anti-Drone)", "sourcePage": 101, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-1-9", "round": 125, "session": 1, "number": 9, "text": "TCP wrapper", "sourcePage": 101, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-1-10", "round": 125, "session": 1, "number": 10, "text": "블록체인 트릴레마 (Trilemma)", "sourcePage": 101, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-1-11", "round": 125, "session": 1, "number": 11, "text": "스마트 공장 (SmartFactory)", "sourcePage": 101, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-1-12", "round": 125, "session": 1, "number": 12, "text": "ISO/IEC25000", "sourcePage": 101, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-1-13", "round": 125, "session": 1, "number": 13, "text": "디바이스 (Device)DNA", "sourcePage": 101, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-2-1", "round": 125, "session": 2, "number": 1, "text": "내부망과 외부망을 분리하는 망분리시스템에 대하여 다음을 설명하시오 . 가 .망분리 개념 및 망분리 원칙 나 .망분리 구축 유형의 특징 비교 다 .망분리 방식의 장 ·단점", "sourcePage": 102, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-2-2", "round": 125, "session": 2, "number": 2, "text": "코드 전송 시 발생하는 오류를 검출 (Detection)할수있을 뿐만 아니라 오류 코드의 정정 (Correction)이가능한 해밍코드 (HammingCode)에 대하여 다음을 설명하시오 . (단,Data는 4Bit로 가정하고 짝수 패리티를 사용한다 .) 가 .해밍코드의 구성 나 .해밍코드의 정정과정 및 정정방법 다 .해밍코드의 활용 사례", "sourcePage": 102, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-2-3", "round": 125, "session": 2, "number": 3, "text": "정보시스템 마스터 플랜 (ISMP,InformationSystemMasterPlan)방법론에 대하여 다음을 설명하시오 . 가 .ISMP정의 나 .ISMP수행 단계 다 .ISP(InformationStrategyPlanning)방법론과의 차이점", "sourcePage": 103, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-2-4", "round": 125, "session": 2, "number": 4, "text": "사업유형이 정보시스템 개발인 경우 정보시스템 감리 점검 프레임워크 V3.0에 따라 다음 두 모델에 대하여 감리시점과 감리영역을 설명하시오 . 가 .구조적 /정보공학적 개발 모델 나 .객체지향 /컴포넌트기반 개발 모델", "sourcePage": 103, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-2-5", "round": 125, "session": 2, "number": 5, "text": "공공안전망에 구현된 RAN-Sharing목적과 기술방식을 각각 설명하시오 .", "sourcePage": 103, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-2-6", "round": 125, "session": 2, "number": 6, "text": "다음의 그림은 서비스 거부 (DDoS,DistributedDenialofService)공격사례이다 . DDoS에 대하여 다음 내용을 설명하시오 . 가 .위 사례의 공격기법 개념 나 .위 사례의 공격기법 다 .공격기법에 대한 보안 대책", "sourcePage": 104, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-3-1", "round": 125, "session": 3, "number": 1, "text": "전송계층 (TransportLayer)에서전송 데이터의 단위는 Segment이다.전송계층 기능 중 흐름제어 (FlowControl)에대하여 다음을 설명하시오 . 가 .흐름제어 방식 개념 나 .흐름제어 방식의 개념도 다 .SlidingWindows와SlowStart비교", "sourcePage": 105, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-3-2", "round": 125, "session": 3, "number": 2, "text": "TCP 전송계층 프로토콜에 대하여 다음을 설명하시오 . 가 .TCP 전송계층 개념 나 .3-wayhandshake와 4-wayhandshake설명 다 .TCP와 UDP 비교", "sourcePage": 105, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-3-3", "round": 125, "session": 3, "number": 3, "text": "CMMI모델에 대하여 다음을 설명하시오 . 가 .프로세스 영역 분류 나 .프로세스 성숙도 레벨", "sourcePage": 105, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-3-4", "round": 125, "session": 3, "number": 4, "text": "디지털 트윈 (DigitalTwins)시스템에 대하여 다음을 설명하시오 . 가 .디지털 트윈의 개념 나 .디지털 트윈의 개념도 다 .디지털 트윈 모델링 5단계", "sourcePage": 106, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-3-5", "round": 125, "session": 3, "number": 5, "text": "클라우드 컴퓨팅 도입 후 클라우드에서 제공하는 다음 서비스에 대하여 설명하시오 . 가 .IaaS(Infrastructureasaservice) 나 .PaaS(Platformasaservice) 다 .SaaS(Softwareasaservice)", "sourcePage": 106, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-3-6", "round": 125, "session": 3, "number": 6, "text": "OTT(OverTheTop)서비스에 대하여 다음을 설명하시오 . 가 .성장 배경 나 .주요 기술 다 .서비스 사업자 유형", "sourcePage": 106, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-4-1", "round": 125, "session": 4, "number": 1, "text": "통신 프로토콜 매체접근제어 방식인 CSMA/CD 개념과 동작원리를 설명하고 I-Persistent,P-Persistent,Non-Persistent경합프로토콜에대하여 각각의 특징 , 장점 및 단점을 설명하시오 .", "sourcePage": 107, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-4-2", "round": 125, "session": 4, "number": 2, "text": "단말 간 직접통신 (DevicetoDeviceCommunication)의운용시나리오 3가지와 활용", "sourcePage": 107, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-4-3", "round": 125, "session": 4, "number": 3, "text": "데이터링크 계층은 네트워크에서 오류제어를 담당한다 .다음을 설명하시오 . 가 .오류제어방식의 개념과 종류 나 .전진오류수정 (FEC)과 검출 후 재전송 (ARQ)방식 비교 다 .ARQ 방식 3가지", "sourcePage": 107, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-4-4", "round": 125, "session": 4, "number": 4, "text": "운영체제 다중 프로그래밍 환경에서 이중 모드 (Dualmode)구조에 대하여 다음을 설명하시오 . 가 .이중모드 개념 나 .이중모드의 구조 다 .이중모드의 종류", "sourcePage": 108, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-4-5", "round": 125, "session": 4, "number": 5, "text": "무선충전기술 3가지 방식을 비교 설명하시오 .", "sourcePage": 108, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "125-4-6", "round": 125, "session": 4, "number": 6, "text": "IoT3대 핵심기술과 NB-IoT3가지 동작모드를 각각 설명하시오 .", "sourcePage": 108, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-1-1", "round": 126, "session": 1, "number": 1, "text": "FANET(FlyingAd-hocNETwork)", "sourcePage": 109, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-1-2", "round": 126, "session": 1, "number": 2, "text": "컴퓨팅 컨티뉴엄 (ComputingContinuum)", "sourcePage": 109, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-1-3", "round": 126, "session": 1, "number": 3, "text": "샌드박스 (Sandbox)의주요구성요소 및 활용분야", "sourcePage": 109, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-1-4", "round": 126, "session": 1, "number": 4, "text": "JTAG(JointTestActionGroup)의제공기능", "sourcePage": 109, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-1-5", "round": 126, "session": 1, "number": 5, "text": "“정보시스템 하드웨어 규모산정 지침 (TTAK.KO-10.0292/R2)”에따른하드웨어규모산정절차", "sourcePage": 109, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-1-6", "round": 126, "session": 1, "number": 6, "text": "ISMS-P(PersonalInformation&InformationSecurityManagementSystem,정보 보호 및 개인정보보호 관리체계 )", "sourcePage": 109, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-1-7", "round": 126, "session": 1, "number": 7, "text": "기능점수 (FunctionPoint)의간이법과정통법", "sourcePage": 109, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-1-8", "round": 126, "session": 1, "number": 8, "text": "서버 클러스터링 구성에서 발생하는 SplitBrain현상", "sourcePage": 109, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-1-9", "round": 126, "session": 1, "number": 9, "text": "세마포어 (Semaphore)", "sourcePage": 109, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-1-10", "round": 126, "session": 1, "number": 10, "text": "데이터 분석 시 결측값 (MissingValue)처리기법", "sourcePage": 109, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-1-11", "round": 126, "session": 1, "number": 11, "text": "양자키분배 (QuantumKeyDistribution)기술", "sourcePage": 109, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-1-12", "round": 126, "session": 1, "number": 12, "text": "엣지컴퓨팅 (EdgeComputing)과포그컴퓨팅(FogComputing)의비교", "sourcePage": 109, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-1-13", "round": 126, "session": 1, "number": 13, "text": "가상메모리 (VirtualMemory)관리기법중 세그먼테이션 (Segmentation)기법", "sourcePage": 109, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-2-1", "round": 126, "session": 2, "number": 1, "text": "인공지능시스템에서 활용되는 CPU,GPU,FPGA,ASIC을설명하고 ,처리 능력과 전력 소비 측면에서 비교하시오 .", "sourcePage": 110, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-2-2", "round": 126, "session": 2, "number": 2, "text": "최근사회적으로 관심이 확대되고 있는 메타버스 (Metaverse)에대하여다음을설명하시오 . 가.메타버스의 정의 나.메타버스의 4가지 유형 다.메타버스의 발전전망 및 문제점", "sourcePage": 110, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-2-3", "round": 126, "session": 2, "number": 3, "text": "지능형 CCTV나 비대면 서비스에서 얼굴 데이터 활용이 증가하고 있다 .이와 관련하여 다음을 설명하시오 . 가.인공지능을 이용한 얼굴정보처리 기술의 개요 나.인공지능을 이용한 얼굴검출 기술 유형 다.YOLO(YouOnlyLookOnce)", "sourcePage": 110, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-2-4", "round": 126, "session": 2, "number": 4, "text": "스마트 팩토리 (SmartFactory)의보안위협과보안 요구사항을 제시하고 ,각 보안 요구 사항별 보안대책에 대하여 설명하시오 .", "sourcePage": 110, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-2-5", "round": 126, "session": 2, "number": 5, "text": "최근 메타버스 산업이 활성화되면서 NFT(NonFungibleToken)의중요성이대두되고 있다 .NFT에 대하여 설명하시오 .", "sourcePage": 110, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-2-6", "round": 126, "session": 2, "number": 6, "text": "5G특화망은 개인을 위한 통신뿐만 아니라 산업환경 전체를 혁신하고 ICT서비스의 차원을 높일 수 있는 핵심적인 경제인프라이다 .이와 관련하여 다음을 설명하시오 . 가.5G이동통신과 5G특화망 각각에 대한 서비스 시장측면 ,네트워크 구축측면 ,통신망 이용측면에서의 특징 비교 나.특화망의 코어망 적용 기술 중 네트워크 슬라이싱 기술 다.5G특화망 활용분야", "sourcePage": 111, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-3-1", "round": 126, "session": 3, "number": 1, "text": "행정안전부에서는 공공기관 등이 정보시스템 사업을 추진할 때 SW 보안약점을 제거 하기 위해 사용하는 “소프트웨어 개발 보안 가이드 ”를 개정 (2021년11월)하였다.이와 관련하여 다음을 설명하시오 . 가.소프트웨어 개발 보안의 정의 ,대상 및 범위 나.소프트웨어 설계 단계 보안 기준 중 “보안기능 입력값 검증 ”과 “업로드·다운로드 파일 검증 ”의개념 및 보안 대책", "sourcePage": 112, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-3-2", "round": 126, "session": 3, "number": 2, "text": "최근 개인정보를 활용하는 서비스 들이 증가하면서 개인정보에 대한 보호가 중요해지고 있다 .이와 관련하여 ISO/IEC29100프라이버시 11개원칙과 ISO/IEC27701개인정보 보호 시스템에 대한 인증 및 평가에 대하여 각각 설명하시오 .", "sourcePage": 112, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-3-3", "round": 126, "session": 3, "number": 3, "text": "드론과 사용자간의 무선통신을 위해 신호다중화 기술 중 FHSS(FrequencyHopping SpreadSpectrum)와DSSS(DirectSequenceSpreadSpectrum)통신방식을활용하고 있다 .이와 관련하여 다음을 설명하시오 . 가.드 론 무선통신을 위한 신호 다중화의 개요와 필요성 나.FHSS 다.DSSS", "sourcePage": 112, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-3-4", "round": 126, "session": 3, "number": 4, "text": "플래시 메모리 (FlashMemory)에대하여다음을 설명하시오 . 가.플래시 메모리의 개요와 구조 나.스 케일다운 한계와 대응방법 다.3D-VerticalNANDFlashMemory", "sourcePage": 113, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-3-5", "round": 126, "session": 3, "number": 5, "text": "마이데이터 서비스에 대하여 다음을 설명하시오 . 가.서비스 절차 나.마이데이터 인증 방식 다.보안 문제점 및 개선 방안", "sourcePage": 113, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-3-6", "round": 126, "session": 3, "number": 6, "text": "휴대용 전자기기 및 전기 자동차 등의 확대로 인해 무선으로 전력을 전송하여 배터리를 충전하는 무선충전기술이 주 목 받고 있다 .이와 관련하여 다음을 설명하시오 . 가.무선충전기술의 개요 나.무선충전기술 유형별 사용 주파수 ,전송거리 및 효율, 인체 유해성 ,주요 사용분야 측면에서 비교 다.무선충전기술 사용에서 발생 가능한 보안 문제점", "sourcePage": 113, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-4-1", "round": 126, "session": 4, "number": 1, "text": "이진트리를 순회하는 방식은 전위순회 ,중위순회 ,후위순회 등으로 나뉜다 .모든 순회 방식은 루트로부터 순회를 시작하여 트리의 모든 노드 들을 반드시 한 번씩 방문하여 순회를 종료한다 .이와 관련하여 다음을 설명하시오 . 가.전위 순회,중위 순회,후위 순회 방식 나.아래 그림의 이진트리를 대상으로 전위순회 ,중위순회, 후위순회를 수행할 때,각각의 방문순서", "sourcePage": 114, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-4-2", "round": 126, "session": 4, "number": 2, "text": "최근 국가적으로 지능형 검침인프라 (AMI:AdvancedMeteringInfrastructure)확산을 추진하고 있다.이와 관련하여 다음을 설명하시오 . 가.AMI구성요소 나.AMI보안 취약요소 다.PKI기반의 스마트 미터 기기 인증시스템", "sourcePage": 115, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-4-3", "round": 126, "session": 4, "number": 3, "text": "귀하는 데이터센터의 운영관리자이다 .최근 다수 장비 들의 전원을 공급하는 UPS(Uninterruptible PowerSupply)시스템에장애 징후가 발생하여 긴급히 교체를 추진하고자 한다 .이러한 상황에서 데이터 센터에서 제공하는 각종 서비스 중단과 영향을 최소화하면서 성공적인 UPS 시스템 교체를 위한 방안을 제시하시오 .", "sourcePage": 115, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-4-4", "round": 126, "session": 4, "number": 4, "text": "소프트웨어진 흥법에 따라 국가기관 등의 장은 상용소프트웨어를 직접 구매하는 경우, 품질성능 평가시 험을 직접하거나 지정 된 시 험기관에 품질성능 평가시 험을 대행하여 수행 할 수 있다 .이와 관련하여 다음을 설명하시오 . 가.평가시 험 적용대상 및 제외기준 나.평가시 험 절차 다.평가시 험 기대효과", "sourcePage": 115, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-4-5", "round": 126, "session": 4, "number": 5, "text": "ARM(AdvancedRISCMachine)프로세서의동 작 모드 종류와 명령어 처리과정에 대하여 설명하시오 .", "sourcePage": 115, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "126-4-6", "round": 126, "session": 4, "number": 6, "text": "5G특화망 구축에 있어 아래 네트워크 구축 기술방식에 대하여 설명하시오 . 가.MPLS-TP및 IP-MPLS기술 개념 및 비교 나.MPLS-TP기 반 백홀망 구축 방안 다.IP-MPLS기반 백홀망 구축 방안", "sourcePage": 116, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-1-1", "round": 128, "session": 1, "number": 1, "text": "DID(DigitalInformationDisplay)", "sourcePage": 117, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-1-2", "round": 128, "session": 1, "number": 2, "text": "SOC(SystemOnChip)구조", "sourcePage": 117, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-1-3", "round": 128, "session": 1, "number": 3, "text": "VM(VirtualMachine)과Container", "sourcePage": 117, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-1-4", "round": 128, "session": 1, "number": 4, "text": "버스중재 (BusArbitration)방식", "sourcePage": 117, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-1-5", "round": 128, "session": 1, "number": 5, "text": "뉴로모픽 (Neuromorphic)반도체", "sourcePage": 117, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-1-6", "round": 128, "session": 1, "number": 6, "text": "DRM(DigitalRightsManagement),DLP(DataLossPrevention)의비교", "sourcePage": 117, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-1-7", "round": 128, "session": 1, "number": 7, "text": "CNN(ConvolutionalNeuralNetwork)계층(Layer)", "sourcePage": 117, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-1-8", "round": 128, "session": 1, "number": 8, "text": "입출력장치 인터페이스의 개념과 필요성", "sourcePage": 117, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-1-9", "round": 128, "session": 1, "number": 9, "text": "시스템 위험분석 (위험성평가 )기법 중 ETA(EventTreeAnalysis)", "sourcePage": 117, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-1-10", "round": 128, "session": 1, "number": 10, "text": "소프트웨어사업 영향평가", "sourcePage": 117, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-1-11", "round": 128, "session": 1, "number": 11, "text": "CAPTCHA(CompletelyAutomatedPublicTuringtesttotellComputersand HumansApart)", "sourcePage": 117, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-1-12", "round": 128, "session": 1, "number": 12, "text": "디피-헬만 알고리즘 (Diffie-HellmanAlgorithm)", "sourcePage": 117, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-1-13", "round": 128, "session": 1, "number": 13, "text": "데이터 독립성 (DataIndependency)", "sourcePage": 117, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-2-1", "round": 128, "session": 2, "number": 1, "text": "네트워크에서 다음 각 주소의 개념과 구조를 설명하시오 . 가 .IP주소 나 .MAC(MediaAccessControl)주소 다 .Port주소 라 .전자메일 주소", "sourcePage": 118, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-2-2", "round": 128, "session": 2, "number": 2, "text": "I/O(Input/Output)전송방식의 필요성과 종류에 대하여 설명하시오 .", "sourcePage": 118, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-2-3", "round": 128, "session": 2, "number": 3, "text": "UAM(UrbanAirMobility)에 대하여 다음을 설명하시오 . 가 .개념 및 특성 나 .eVTOL(electricVerticalTake-OffandLanding)추진기술 다 .K-UAM(Korea-UAM)로드맵 라 .UAM(UrbanAirMobility)통신 네트워크 인프라 연계방안", "sourcePage": 118, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-2-4", "round": 128, "session": 2, "number": 4, "text": "기업은 다양한 솔루션을 도입하여 보안 관제시스템을 운영하고 있으며 ,보다 효율적인 운영을 위해 융합보안관제를 구축하고자 한다 .이와 관련하여 다음을 설명하시오 . 가 .융합보안관제의 필요성 나 .구축 시 고려사항과 활용기술 다 .구축 시 시스템 구성요소", "sourcePage": 118, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-2-5", "round": 128, "session": 2, "number": 5, "text": "소프트웨어 안전 관리에 대하여 다음을 설명하시오 . 가 .소프트웨어 안전의 정의 나 .안전 ,보안 ,품질의 비교 다 .소프트웨어 안전 진단 영역 3가지 라 .위험도 (Risk)와위험원 (Hazard)과 관련된 GAMAB(GlobalementAuMoins AussiBon)원칙과 ALARP(AsLowAsReasonablePracticable)원칙", "sourcePage": 119, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-2-6", "round": 128, "session": 2, "number": 6, "text": "인공지능 학습에서 두 객체가 얼마나 유사한지를 나타내는 척도를 유사도 (Similarity)라고 한다 .다음을 설명하시오 . 가 .자카드 유사도 (JaccardSimilarity) 나 .코사인 유사도 (CosineSimilarity) 다 .실루엣 계수 (SilhouetteCoefficient)", "sourcePage": 119, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-3-1", "round": 128, "session": 3, "number": 1, "text": "계층구조의 통신 프로토콜 설계 시 고려해야 할 다음 각 요소에 대하여 설명하시오 . 가 .오류 제어 나 .흐름 제어 다 .데이터 전달 방식", "sourcePage": 120, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-3-2", "round": 128, "session": 3, "number": 2, "text": "TCP(TransmissionControlProtocol)에 대하여 다음을 설명하시오 . 가 .TCP 헤더 (header) 나 .TCP 헤더에 포함된 제어 플래그 (ControlFlag)의 종류", "sourcePage": 120, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-3-3", "round": 128, "session": 3, "number": 3, "text": "디지털 포렌식 (forensic)과정에서 실제로 증거를 수집하려면 네트워크 , 시스템 , 데이터 베이스 및 응용 프로그램 등 다양한 분야에 관한 지식이 필요하다 .다음 각 분야에서 디지털 포렌식의 증거를 수집하기 위한 방법을 설명하시오 . 가 .네트워크 증거 수집 나 .시스템 증거 수집 다 .응용 프로그램 증거 수집", "sourcePage": 120, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-3-4", "round": 128, "session": 3, "number": 4, "text": "클라우드 서비스 제공자는 AIaaS(AIasa Service)를통해 인공지능을 쉽게 이용 할 수 있도록 다양한 API(ApplicationProgramInterface)를 제공한다 .다음 항목을 설명하시오 . 가 .AIaaS개념 및 특징 나 .AIaaS구조 다 .아마존 웹서비스 (AWS)와 렉스 (Lex)", "sourcePage": 121, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-3-5", "round": 128, "session": 3, "number": 5, "text": "KS X ISO/IEC/IEEE29119을 활용하여 다음을 설명하시오 . 가 .테스트 설계 및 구현 프로 세 스 나 .테스트 설계 기법 다 .ISO/IEC25010에서 정의한 테스트 품질특성과 명 세 기반 테스트 설계 기 법 간의 매핑", "sourcePage": 121, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-3-6", "round": 128, "session": 3, "number": 6, "text": "관계 데이터 모 델이 가지고 있는 개체 무결 성 (EntityIntegrity)과참조 무결 성 (ReferentialIntegrity)에대하여 설명하시오 .", "sourcePage": 121, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-4-1", "round": 128, "session": 4, "number": 1, "text": "머신 러닝 (MachineLearning)에서 교 차검 증 (CrossValidation)에대하여 설명하시오 .", "sourcePage": 122, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-4-2", "round": 128, "session": 4, "number": 2, "text": "5G 와 6G이 동통신에 대한 특징과 발전 동향에 대하여 설명하시오 .", "sourcePage": 122, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-4-3", "round": 128, "session": 4, "number": 3, "text": "엣지 컴퓨팅 (EdgeComputing)의 장단 점과 적용사 례 및 보안 취약점 에 대하여 설명하시오 .", "sourcePage": 122, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-4-4", "round": 128, "session": 4, "number": 4, "text": "대용 량 비 휘발 성 저 장장치로 불리우는 SSD(SolidStateDrive)제어기의 플래시 변환 계층 (FlashTranslationLayer)에대하여 설명하시오 .", "sourcePage": 122, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-4-5", "round": 128, "session": 4, "number": 5, "text": "의 료용 3D(Dimension)모델링 소프트웨어 관련으로 다음을 설명하시오 . 가 .3D프 린팅 개념 및 정의 나 .3D프 린팅 공정 분류 및 설명 다 .의 료용 3D모 델링 소프트웨어 품질 평가항목", "sourcePage": 122, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "128-4-6", "round": 128, "session": 4, "number": 6, "text": "클라우드 서비스의 품질 ⋅ 성능에 관한 기 준 제정의 추진 배경 및 평가 기 준에 대하여 작성하고 ,서비스 회복 시 간의 정 량 적 측정을 위한 지 표에 대하여 설명하시오 .", "sourcePage": 122, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-1-1", "round": 129, "session": 1, "number": 1, "text": "PIM(ProcessinginMemory)", "sourcePage": 123, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-1-2", "round": 129, "session": 1, "number": 2, "text": "CSAP(CloudSecurityAssuranceProgram)", "sourcePage": 123, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-1-3", "round": 129, "session": 1, "number": 3, "text": "웹 애플리케이션 방화벽 (WAF :WebApplicationFirewall)", "sourcePage": 123, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-1-4", "round": 129, "session": 1, "number": 4, "text": "스마트양식장 (SmartFishFarm)", "sourcePage": 123, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-1-5", "round": 129, "session": 1, "number": 5, "text": "페어 프로그래밍 (PairProgramming)기법과핑퐁프로그래밍 (PingPongProgramming) 기법에 대하여 각각 설명하시오 .", "sourcePage": 123, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-1-6", "round": 129, "session": 1, "number": 6, "text": "3-상태 버퍼 (Tri-StateBuffer)", "sourcePage": 123, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-1-7", "round": 129, "session": 1, "number": 7, "text": "소프트웨어 리팩토링 (Refactoring)", "sourcePage": 123, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-1-8", "round": 129, "session": 1, "number": 8, "text": "전송 부호화 기법의 소스코딩 (SourceCoding)과채널코딩(ChannelCoding)을비교 하여 설명하시오 .", "sourcePage": 123, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-1-9", "round": 129, "session": 1, "number": 9, "text": "HBM(High BandwidthMemory)", "sourcePage": 123, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-1-10", "round": 129, "session": 1, "number": 10, "text": "자동차 통신 등에 활용하는 CAN(ControllerAreaNetwork)통신", "sourcePage": 123, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-1-11", "round": 129, "session": 1, "number": 11, "text": "튜링테스트 (TuringTest)", "sourcePage": 123, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-1-12", "round": 129, "session": 1, "number": 12, "text": "CacheMemory의 쓰기 정책인 WriteThrough방식과 WriteBack방식을 비교 하여 설명하시오 .", "sourcePage": 123, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-1-13", "round": 129, "session": 1, "number": 13, "text": "상용소프트웨어 직접구매 제도", "sourcePage": 123, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-2-1", "round": 129, "session": 2, "number": 1, "text": "CXL(ComputeExpressLink)에대하여다음을 설명하시오 . (1)CXL의 목적 (2)CXL의 3가지 프로토콜인 CXL.io,CXL.cache및CXL.memory (3)CXL의 디바이스 유형인 Type1디바이스 ,Type2디바이스 및 Type3 디바이스", "sourcePage": 124, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-2-2", "round": 129, "session": 2, "number": 2, "text": "데이터센터와 관련하여 미국통신산업협회 (TelecommunicationIndustryAssociation) TIA-942가이드라인에 대하여 다음을 설명하시오 . (1)TIA-942개요 (2)TIA-942품질 등급", "sourcePage": 124, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-2-3", "round": 129, "session": 2, "number": 3, "text": "MIV(MPEG-ImmersiveVideo)에대하여설명하시오 .", "sourcePage": 124, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-2-4", "round": 129, "session": 2, "number": 4, "text": "리먼(Lehman)의소프트웨어 진화 법칙 에 대하여 설명하시오 .", "sourcePage": 124, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-2-5", "round": 129, "session": 2, "number": 5, "text": "“정보시스템 하드웨어 규모산정 지침 (TTAK.KO-10.0292/R2)”과관련하여다음을 설명하시오 . (1)규모산정 방법 (2)규모산정 대상 (3)규모산정 절차", "sourcePage": 125, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-2-6", "round": 129, "session": 2, "number": 6, "text": "사용자 테스트와 관련하여 다음을 설명하시오 . (1)알파 (Alpha)테스트 (2)베타 (Beta)테스트 (3)인수 (Acceptance)테스트 (4)인수 테스트 프로세스 (AcceptanceTestProcess)", "sourcePage": 125, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-3-1", "round": 129, "session": 3, "number": 1, "text": "운영체제 프로세스 스케줄링 알고리즘과 관련하여 단일 큐 멀티프로세서 스케줄링 (SQMS:SingleQueueMultiprocessorScheduling)과멀티큐멀티프로세서스케줄링 (MQMS :MultiQueueMultiprocessorScheduling)을각각설명하시오.", "sourcePage": 126, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-3-2", "round": 129, "session": 3, "number": 2, "text": "네트워크 스위치 (NetworkSwitch)와관련하여 다음을 설명하시오 . (1)스위치 개요 (2)OSI(OpenSystemInterconnection)참조모델의레이어에 따른 스위치 유형 (3)L4스위치와 L7스위치 비교", "sourcePage": 126, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-3-3", "round": 129, "session": 3, "number": 3, "text": "최근 의료기관을 대상으로 사이버 침해공격이 지능화 및 다양화되고 있다 .이에 대한 대안으로 병원정보시스템 (HIS:HospitalInformationSystem)에특화된정보공유센터 (ISAC:InformationSharingAnalysisCenter)의역할이증가하고있다.이와 관련하여 다음을 설명하시오 . (1)HIS의 개요 및 구성 (2)ISAC의 개요 및 역할 (3)의료기관의 사이버침해공격 대응방안", "sourcePage": 126, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-3-4", "round": 129, "session": 3, "number": 4, "text": "양자 컴퓨터 (QuantumComputer)와관련하여 다음을 설명하시오 . (1)양자비트 (Qubit,큐비트),양자 우월성 (QuantumSupremacy),양자결잃음 (Quantum Decoherence) (2)양자 컴퓨터 구현 방법", "sourcePage": 127, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-3-5", "round": 129, "session": 3, "number": 5, "text": "이더넷 (Ethernet)표준에대하여 다음을 설명하시오 . (1)정의 및 특징 (2)IEEE802.3프레임 (Frame)구조 (3)전송 프레임의 최소 크기가 64바이트인 이유", "sourcePage": 127, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-3-6", "round": 129, "session": 3, "number": 6, "text": "DDR SDRAM(DoubleDateRateSynchronousDRAM)의갱신 (Refresh)에대하여 다음을 설명하시오 . (1)DRAM 에서 갱신 (Refresh)이필요한 이유 (2)자동 갱신 (AutoRefresh) (3)셀프 갱신 (SelfRefresh) (4)저전력 자동 셀프 갱신 (LPASR :LowPowerAutoSelfRefresh)", "sourcePage": 127, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-4-1", "round": 129, "session": 4, "number": 1, "text": "다음 표준 통신 프로토콜에 대하여 설명하시오 . (1)TCP(TransmissionControlProtocol) (2)UDP(UserDatagramProtocol) (3)SCTP(StreamingControlTransmissionProtocol) (4)TCP,UDP,SCTP 비교", "sourcePage": 128, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-4-2", "round": 129, "session": 4, "number": 2, "text": "Ad-hoc라우팅 프로토콜과 관련하여 다음을 설명하시오 . (1)Ad-hoc라우팅 프로토콜 개요 (2)Ad-hoc라우팅 프로토콜 유형 (3)AODV(Ad-hocOn-DemandVector)", "sourcePage": 128, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-4-3", "round": 129, "session": 4, "number": 3, "text": "디스크 이미징 (DiskImaging)과관련하여 다음을 설명하시오 . (1)디스크 이미징 용도 (2)DisktoDisk와DisktoFile방식을 각각 설명 (3)디스크 이미징을 활용한 증거수 집 방법", "sourcePage": 128, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-4-4", "round": 129, "session": 4, "number": 4, "text": "인공지능 생 태계 에서 벤치마크 데이터 셋 의 개요와 주 요 역할에 대하여 설명하시오 .", "sourcePage": 129, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-4-5", "round": 129, "session": 4, "number": 5, "text": "2022년9월 2일 정부는 디지 털 플랫폼 정부위원회 를 설립 하고 기존 정부의 파이프라인 비 즈니 스 형태 를 디지 털플 랫폼 형태로 변화 를 추 진하고 있다 .디지 털 플랫폼 정부의 개요와 추진 방안에 대하여 설명하시오 .", "sourcePage": 129, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "129-4-6", "round": 129, "session": 4, "number": 6, "text": "무선충 전기 술 과 관련하여 다음을 설명하시오 . (1)무선충 전기 술 개요 (2)무선충 전기 술 유형 (3)무선충 전기 술의 표준화 동향", "sourcePage": 129, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-1-1", "round": 131, "session": 1, "number": 1, "text": "몬테 카를로 방법 (MonteCarloMethod)", "sourcePage": 130, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-1-2", "round": 131, "session": 1, "number": 2, "text": "NaaS(NetworkasaService)", "sourcePage": 130, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-1-3", "round": 131, "session": 1, "number": 3, "text": "오토인코더 (Autoencoder)", "sourcePage": 130, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-1-4", "round": 131, "session": 1, "number": 4, "text": "전이학습 (TransferLearning)", "sourcePage": 130, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-1-5", "round": 131, "session": 1, "number": 5, "text": "ATAM(ArchitectureTrade-offAnalysisMethod)과CBAM(CostBenefitAnalysis Method)", "sourcePage": 130, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-1-6", "round": 131, "session": 1, "number": 6, "text": "PNM(ProcessingNearMemory)", "sourcePage": 130, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-1-7", "round": 131, "session": 1, "number": 7, "text": "NoSQL의 CAP(Consistency,Availability,PartitionTolerance)", "sourcePage": 130, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-1-8", "round": 131, "session": 1, "number": 8, "text": "RPA(RoboticProcessAutomation)", "sourcePage": 130, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-1-9", "round": 131, "session": 1, "number": 9, "text": "알고리즘의 시간복잡도 (TimeComplexity),공간복잡도(SpaceComplexity)", "sourcePage": 130, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-1-10", "round": 131, "session": 1, "number": 10, "text": "지능정보화 기본법", "sourcePage": 130, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-1-11", "round": 131, "session": 1, "number": 11, "text": "xAPI(eXperienceApplicationInterface)", "sourcePage": 130, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-1-12", "round": 131, "session": 1, "number": 12, "text": "CBPR(CrossBorderPrivacyRule)", "sourcePage": 130, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-1-13", "round": 131, "session": 1, "number": 13, "text": "CSRF(Cross-SiteRequestForgery)", "sourcePage": 130, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-2-1", "round": 131, "session": 2, "number": 1, "text": "마르코프 특성 (MarkovProperty)은 미래 상태의 조건부 확률분포가 과거 상태와는 독립적으로 현재 상태에 의해서만 결정된다는 것을 뜻한다 . 이와 관련하여 다음을 설명하시오 . 가 .마르코프 결정 프로세스 (MarkovDecisionProcess)와전이확률 (TransitionProbability) 나 .상태가치함수 (StateValueFunction)와액션가치함수 (State-ActionValueFunction) 다 .벨만기대방정식 (BellmanExpectationEquation)과벨만최적방정식(BellmanOptimalityEquation)", "sourcePage": 131, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-2-2", "round": 131, "session": 2, "number": 2, "text": "프로세스 스레싱 (Thrashing)의 정의 ,발생 원인과 해결방법을 설명하시오 .", "sourcePage": 131, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-2-3", "round": 131, "session": 2, "number": 3, "text": "현행 데이터베이스 데이터량을 기준으로 TO-BE데이터량을 예측하고자 한다 . 이와 관련하여 다음을 설명하시오 . 가 .데이터베이스 용량산정 방법 별 개념 및 장 ·단점 나 .데이터베이스 용량산정 기준", "sourcePage": 131, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-2-4", "round": 131, "session": 2, "number": 4, "text": "네트워크 자원을 보다 효율적으로 관리하고 최적화하기 위해 ,네트워크 인프라에 머신 러닝 기법을 적용하고 있다 .이와 관련하여 다음을 설명하시오 . 가 . 네트워크 인프라에 SDN(SoftwareDefinedNetworking)을 이용하여 머신러닝 기법을 적용하는 이유 나 . SDN에서 강화학습 적용방안", "sourcePage": 132, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-2-5", "round": 131, "session": 2, "number": 5, "text": "칩렛 (Chiplet)에대하여 다음을 설명하시오 . 가 . 칩렛의 개념 나 . 칩렛 구조의 장점 다 . 칩렛을 이어붙이는 방법", "sourcePage": 132, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-2-6", "round": 131, "session": 2, "number": 6, "text": "클라우드 서비스에 대하여 다음을 설명하시오 . 가 . IT자원 유형에 따른 분류 나 . 서비스 개방 여부에 따른 분류 다 . MSP(ManagedServiceProvider)의 역할", "sourcePage": 132, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-3-1", "round": 131, "session": 3, "number": 1, "text": "현재의 딥러닝 기술은 사람의 눈으로 식별되지 않을 만큼 작은 노이즈를 추가해서 만든 적대적 예제 (AdversarialExample)를 활용한 공격에 취약하다 . 이와 관련하여 다음을 설명하시오 . 가 .White-box및 Black-box적대적 공격에 대한 개념과 장 ·단점 비교 나 . 적대적 훈련 (AdversarialTraining)및 DefenseGAN(GenerativeAdversarial Networks)방어기법", "sourcePage": 133, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-3-2", "round": 131, "session": 3, "number": 2, "text": "개인정보 비식별 처리와 관련하여 다음을 설명하시오 . 가 .개인정보 비식별 처리 유형 나 .비식별 개인정보의 위험 요인", "sourcePage": 133, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-3-3", "round": 131, "session": 3, "number": 3, "text": "디스크 여러 개를 활용하여 속도를 높이고 안정성을 향상시키는 기술인 RAID(RedundantArrayofInexpensiveDisk)기술 중 RAID5와 RAID6에 대하여 설명하고 ,최소 디스크 수량 및 고장 허용 측면에서 비교하여 설명하시오 .", "sourcePage": 133, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-3-4", "round": 131, "session": 3, "number": 4, "text": "데이터베이스에 사용되는 트랜잭션의 개념과 이를 정의하는 4가지 중요한 속성을 가리키는 ACID의 각 요소에 대하여 설명하시오 .", "sourcePage": 134, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-3-5", "round": 131, "session": 3, "number": 5, "text": "공공기관 정보화 사업 추진 시 국가정보원 보안성 검토 절차를 설명하시오 .", "sourcePage": 134, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-3-6", "round": 131, "session": 3, "number": 6, "text": "데이터옵스 (DataOps)의 주요 기술을 설명하고 ,데브옵스 (DevOps)와의 차이점을 설명하시오 .", "sourcePage": 134, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-4-1", "round": 131, "session": 4, "number": 1, "text": "강화학습 (ReinforcementLearning)은최적의 행동정책을 찾아가는 기계학습 방법이다 . 이와 관련하여 다음을 설명하시오 . 가 .가치기 반 강화학습 ,정책기 반 강화학습 ,액터 크리 틱(Actor-Critic)강화학습 나 .정책 경 사(PolicyGradient)방식 강화학습", "sourcePage": 135, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-4-2", "round": 131, "session": 4, "number": 2, "text": "추천 시스 템은 사용자의 과거 행동데이터 등을 바탕 으로 사용자가 좋아할 만한 정보나 제품 을 제시해 주는 시스 템이다 .이와 관련하여 다음을 설명하시오 . 가 . 컨텐츠 기 반 필 터링 (Content-basedFiltering)과협 업적 필터 링 (Collaborative Filtering)기법 나 .행 렬 분해 (MatrixFactorization)기반 협업적 필 터링", "sourcePage": 135, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-4-3", "round": 131, "session": 4, "number": 3, "text": "캐쉬 메모 리(CacheMemory)에 대하여 다음을 설명하시오 . 가 .캐쉬 메모 리의 개념과 구조 나 .지역성 (Locality)의개념과 유형 다 .캐쉬 일관성 (Coherence)문제의 원인과 해결 방법", "sourcePage": 135, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-4-4", "round": 131, "session": 4, "number": 4, "text": "스마트 홈 연결 표 준인 매 터 (Matter)에대하여 다음을 설명하시오 . 가 .매 터의 개념 나 .기 존 스마트 홈 표준의 한계점과 매 터의 장점 다 .매 터 NetworkStack", "sourcePage": 136, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-4-5", "round": 131, "session": 4, "number": 5, "text": "시스 템 성능 테스트 수행 시 성능 지 표 관련하여 다음 물 음에 답 하시오 . 가 .응답 시간 (ResponseTime),대기시간 (ThinkTime),동시사용자 (ConcurrentUser), 활성사용자 (ActiveUser),TPS(TransactionPerSecond)를 설명하시오 . 나 .동시사용자 (ConcurrentUser)가 100명이고 ,응답 시간 (ResponseTime)이 5초 이 내 이 며 ,대기시간 (ThinkTime)이 15초 인 시스 템 의 경 우 ,TPS를 구하시오", "sourcePage": 136, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "131-4-6", "round": 131, "session": 4, "number": 6, "text": "공공기관 정보화 사업 추진 시 상용 SW 직접 구 매 제도와 관련하여 다음을 설명하시오 . 가 .상용 SW 직접 구 매 적용대상 나 .상용 SW 직접 구 매 예외 기준 다 .상용 SW 직접 구 매 와 일괄 발주 비교", "sourcePage": 136, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-1-1", "round": 132, "session": 1, "number": 1, "text": "TCAM(TernaryContentAddressableMemory)의개념과활용사례", "sourcePage": 137, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-1-2", "round": 132, "session": 1, "number": 2, "text": "폴락의 법칙 (Pollack’sRule)", "sourcePage": 137, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-1-3", "round": 132, "session": 1, "number": 3, "text": "CanaryTest", "sourcePage": 137, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-1-4", "round": 132, "session": 1, "number": 4, "text": "세마포어 (Semaphore)의개념과 주요 연산 (P연산,V연산 )", "sourcePage": 137, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-1-5", "round": 132, "session": 1, "number": 5, "text": "전송 제어 프로토콜 (TCP,TransmissionControlProtocol)의4-wayhandshake", "sourcePage": 137, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-1-6", "round": 132, "session": 1, "number": 6, "text": "“소프트웨어 기술성 평가기준 지침 ”(과학기술정보통신부고시 ,제2021-98호)에 명시된 기술제안서 평가항목", "sourcePage": 137, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-1-7", "round": 132, "session": 1, "number": 7, "text": "전자정부사업관리 위탁 (PMO,ProjectManagementOffice)", "sourcePage": 137, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-1-8", "round": 132, "session": 1, "number": 8, "text": "디지털 리터러시 (DigitalLiteracy)", "sourcePage": 137, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-1-9", "round": 132, "session": 1, "number": 9, "text": "네트워크 실시간 측위 (NRTK,NetworkRealTimeKinematic)", "sourcePage": 137, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-1-10", "round": 132, "session": 1, "number": 10, "text": "만리장성 모델 (ChineseWallModel,Brewer-NashModel)", "sourcePage": 137, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-1-11", "round": 132, "session": 1, "number": 11, "text": "파인튜닝 (Fine-tuning)", "sourcePage": 137, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-1-12", "round": 132, "session": 1, "number": 12, "text": "영지식 증명 (ZeroKnowledgeProof)", "sourcePage": 137, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-1-13", "round": 132, "session": 1, "number": 13, "text": "슈퍼 앱(SuperAPP)", "sourcePage": 137, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-2-1", "round": 132, "session": 2, "number": 1, "text": "컴퓨터 시스템은 내부/외부에서 발생하는 각종 event에대처하기 위해 ,다양한 방식으로 인터럽트 (interrupt)체계를구현하고있다 .이와 관련하여 아래 사항을 설명하시오 . 가.Polling방식 나.Daisy-Chain방식 다.VectorInterrupt방식", "sourcePage": 138, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-2-2", "round": 132, "session": 2, "number": 2, "text": "사물인터넷은 일생생활에서 AI와융합되어 지능형 IoT로진화하고 있다 .이와 관련하여 아래 사항을 설명하시오 . 가.AIoT(ArtificialIntelligenceofThings)개념 나.AIoT의 보안 취약점 다.AIoT디바이스 보안기술 3가지", "sourcePage": 138, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-2-3", "round": 132, "session": 2, "number": 3, "text": "인터넷 제어 메시지 프로토콜 (ICMP,InternetControlMessageProtocol)과인터넷그룹 관리 프로토콜 (IGMP,InternetGroupManagementProtocol)을비교하여설명하시오.", "sourcePage": 138, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-2-4", "round": 132, "session": 2, "number": 4, "text": "이동형 로봇의 대인 충돌 안전성 평가 방법 (정보통신단체표준 ,TTAK.KO-10.1223)에 대하여 아래 사항을 설명하시오 . 가.충돌 시험에서의 충격 속도 측정방법 나.충돌 시험용 인체모형 (더미,dummy) 다.인체모형 측정 데이터", "sourcePage": 139, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-2-5", "round": 132, "session": 2, "number": 5, "text": "정보시스템 마스터플랜 (ISMP,InformationSystemMasterPlan)에대하여아래사항을 설명하시오 . 가.ISMP와 EA(EnterpriseArchitecture),ISP(InformationSystemPlanning)에대하여 각각 설명하고 상호 비교 나.투입공수에 의한 사업대가 산정방식을 적용한 ISMP수립비 산정 절차,주요내용 ,산출물", "sourcePage": 139, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-2-6", "round": 132, "session": 2, "number": 6, "text": "개방형 무선 접속망 OpenRAN(OpenRadioAccessNetwork)은서로 다른 장비 간 상호 연동을 가능하게 하는 기술이다 .이와 관련하여 아래 사항을 설명하시오 . 가.OpenRAN의 개념 나.OpenRAN의 구성요소 다.RAN과 OpenRAN의 비교", "sourcePage": 139, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-3-1", "round": 132, "session": 3, "number": 1, "text": "앰비언트 컴퓨팅 (AmbientComputing)은인간의개입이없어도 시스템이 스스로 동작하는 기술이다 .이와 관련하여 아래 사항을 설명하시오 . 가.앰비언트 컴퓨팅의 개념 나.개념도 및 기술요소 다.앰비언트 컴퓨팅과 IoT(InternetofThings)비교", "sourcePage": 140, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-3-2", "round": 132, "session": 3, "number": 2, "text": "가상머신 (VirtualMachine)과컨테이너(Container)에대하여구체적으로설명하고,공통점과 차이점을 상세히 설명하시오 .", "sourcePage": 140, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-3-3", "round": 132, "session": 3, "number": 3, "text": "맨체스터 코딩 (ManchesterCoding)은데이터저장과 디지털 데이터 통신 분야에서 다양하게 활용되는 코딩방식이다 .이와 관련하여 아래사항을 설명하시오 . 가.맨체스터 (Manchester)코딩방식의개념 나.맨체스터 인코딩 및 디코딩 다.맨체스터 코딩방식과 차등(Differential)맨체스터코딩방식 비교", "sourcePage": 140, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-3-4", "round": 132, "session": 3, "number": 4, "text": "중앙처리장치 (CPU)내에 구성된 제어장치 (ControlUnit)의구현방법과 관련하여 아래 사항을 설명하시오 . 가.micro-programmed구현방법 나.hard-wired구현방법 다.구현 방법 간 상호비교", "sourcePage": 141, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-3-5", "round": 132, "session": 3, "number": 5, "text": "객체 지 향 프로그래 밍 기법을 활용한 소프트웨어 설계 시 고 려해야 할 원칙(일명 SOLID원칙) 5가지를 제시하고 설명하시오 .", "sourcePage": 141, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-3-6", "round": 132, "session": 3, "number": 6, "text": "정보통신산업진 흥원 에서 제시한 소프트웨어사업 영향평가에 대하여 아래 사항을 설명하시오 . 가.영향평가 대상기관 나.소프트웨어사업 영향 평가 체계 다.평가항목", "sourcePage": 141, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-4-1", "round": 132, "session": 4, "number": 1, "text": "컴퓨터 시스템의 캐시 (Cache)메모리와 관련하여 아래 사항을 설명하시오 . 가.캐시메모리에서 주소 매핑(mapping)이필요한 이유와 주소 매핑 (mapping)방식 나.캐시 쓰기 정책(writepolicy) 다.다중 프로세서 시스템에서 캐 시 일관성 (CacheCoherence)을유지하기위한 기법", "sourcePage": 142, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-4-2", "round": 132, "session": 4, "number": 2, "text": "한국지능정보사 회진흥원 에서 제시한 클라우드 서비스 활용사업 감리 점 검에 대하여 아래 사항을 설명하시오 . 가.공공부 문의 클라우드 사업 유 형 나.클라우드 서비스 활용사업의 점검 단계 ,활동 ,검토항목", "sourcePage": 142, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-4-3", "round": 132, "session": 4, "number": 3, "text": "디지털 트윈 기술을 이용한 제조(정보통신단체표준 ,TTAK.KO-11.0284)에대하여아래 사항을 설명하시오 . 가.제조를 위한 디지털 트윈 (digitaltwin)기술개념 나.제조 디지털 트윈(digitaltwin)프레임워크 다.액터(actor)정보 테이 블의 항목 및 항목 값", "sourcePage": 142, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-4-4", "round": 132, "session": 4, "number": 4, "text": "운영체제에서 발생 할 수 있는 deadlock현상에대하여 아래 사항을 설명하시오 . 가.deadlock의개념 나.deadlock과starvation의차이점 다.deadlock이발생하기 위한 조건 4가지 라.deadlock발생시 처리 방안", "sourcePage": 143, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-4-5", "round": 132, "session": 4, "number": 5, "text": "서포트 벡 터 머신 (SupportVectorMachine)은기계학습분야에서 많이 활용되는 학습 모델이다 .아래 사항을 설명하시오 . 가.SVM의 개념 나.SVM의 동작방식 다.SVM의 장단점 및 활용사례", "sourcePage": 143, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "132-4-6", "round": 132, "session": 4, "number": 6, "text": "초저지연 서비스와 부하분산을 위한 모바일 엣 지 컴퓨팅 (MobileEdgeComputing) 기술이 확대되고 있다 .아래 사항을 설명하시오 . 가.모바일 엣 지 컴퓨팅의 개념 나.모바일 엣 지 컴퓨팅의 플 랫폼 구조 및 구성요소 다.모바일 5G에서 엣지 컴퓨팅 적용 방안", "sourcePage": 143, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-1-1", "round": 134, "session": 1, "number": 1, "text": "Wi-Fi7", "sourcePage": 144, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-1-2", "round": 134, "session": 1, "number": 2, "text": "제로데이 (ZeroDay)취약점", "sourcePage": 144, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-1-3", "round": 134, "session": 1, "number": 3, "text": "온디바이스 AI", "sourcePage": 144, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-1-4", "round": 134, "session": 1, "number": 4, "text": "촉각 인터넷 (TactileInternet)", "sourcePage": 144, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-1-5", "round": 134, "session": 1, "number": 5, "text": "제로 트러스트 (ZeroTrust)", "sourcePage": 144, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-1-6", "round": 134, "session": 1, "number": 6, "text": "동적 WEP 키 (DynamicWEP Key)", "sourcePage": 144, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-1-7", "round": 134, "session": 1, "number": 7, "text": "SBOM(SoftwareBillofMaterials)", "sourcePage": 144, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-1-8", "round": 134, "session": 1, "number": 8, "text": "신경망 처리장치 (NPU:NeuralProcessingUnit)", "sourcePage": 144, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-1-9", "round": 134, "session": 1, "number": 9, "text": "플랫폼 엔지니어링 (PlatformEngineering)", "sourcePage": 144, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-1-10", "round": 134, "session": 1, "number": 10, "text": "「행정기관 및 공공기관의 클라우드 컴퓨팅 서비스 이용 기준 및 안전성 확보 등에 관한 고시 」의 서비스 운영 분야 안전성 검토 항목", "sourcePage": 144, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-1-11", "round": 134, "session": 1, "number": 11, "text": "애자일 (Agile)소프트웨어 개발의 장점 및 단점", "sourcePage": 144, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-1-12", "round": 134, "session": 1, "number": 12, "text": "전자정부 정보시스템 성과 측정지표", "sourcePage": 144, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-1-13", "round": 134, "session": 1, "number": 13, "text": "소프트웨어 품질성능 평가시험", "sourcePage": 144, "category": "컴퓨터 시스템 평가", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-2-1", "round": 134, "session": 2, "number": 1, "text": "PoE(PowerofEthernet)에 관하여 다음 사항을 설명하시오 . 가 . 개념 나 . IEEE표준 다 . 국내 기술기준", "sourcePage": 145, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-2-2", "round": 134, "session": 2, "number": 2, "text": "최근 초거대 인공지능 (AI:ArtificialIntelligence)도입및활용에 필요한 사항을 담은 “공공 부문 초거대 AI 도입 ·활용 가이드라인 ”이 발표되었다 .다음 항목에 관하여 설명하시오 . 가 . 초거대 AI 개념 나 . 초거대 AI 도입 원칙 다 . 초거대 AI 도입 시 사전 고려사항", "sourcePage": 145, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-2-3", "round": 134, "session": 2, "number": 3, "text": "최근 정보보호 및 개인정보보호 관리체계 인증 (ISMS-P)에 대한 간편인증이 발표 되었다 .다음에 대하여 설명하시오 . 가 . ISMS-P 간편인증 목적 나 . ISMS-P 간편인증 대상 다 . ISMS-P 간편인증 기준", "sourcePage": 145, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-2-4", "round": 134, "session": 2, "number": 4, "text": "스 푸핑 (Spoofing)공격에 대하여 다음을 설명하시오 . 가 . 스푸핑 공격의 개념 나 . ARP스푸핑 공격 방법과 보안 대책 다 . IP스푸핑 공격 방법과 보안 대책 라 . DNS 스푸핑 공격 방법과 보안 대책", "sourcePage": 146, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-2-5", "round": 134, "session": 2, "number": 5, "text": "교착 상태 (Deadlock)에 대하여 다음을 설명하시오 . 가 . 교착 상태의 개념 나 . 교착 상태의 필요조건 다 . 교착 상태의 해결 방법", "sourcePage": 146, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-2-6", "round": 134, "session": 2, "number": 6, "text": "OSI 7 계층 (Layer)에 대하여 계층별 다음 사항을 설명하시오 . 가 . 기능 나 . 프로토콜 종류 다 . 데이터 종류 라 . 주요 장비", "sourcePage": 146, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-3-1", "round": 134, "session": 3, "number": 1, "text": "정보기술 아키텍처의 도입과 운영에 필요한 사항을 정하기 위한 “정보기술 아키텍처 (EA:EnterpriseArchitecture)도입·운영 지침 ”과 관련하여 다음을 설명하시오 . 가 .범정부 정보기술 아키텍처 메타모델 나 .범정부 정보기술 아키텍처 참조모형의 종류 다 .범정부 정보기술 아키텍처 성숙도 모델", "sourcePage": 147, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-3-2", "round": 134, "session": 3, "number": 2, "text": "빅데이터 관련 정보화 사업에 대한 감리 수행 점검항목을 제시하는 “지능정보기술 감리 실무 가이드 ”에 대해서 다음을 설명하시오 . 가 .빅데이터 분석단계 점검항목 나 .클라우드 계획수립 점검항목", "sourcePage": 147, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-3-3", "round": 134, "session": 3, "number": 3, "text": "디지털 계위 (DigitalHierarchy)에관한 다음 사항에 대하여 설명하시오 . 가 .PDH(PlesiochronousDigitalHierarchy) 나 .SDH(SynchronousDigitalHierarchy) 다 .SONET(SynchronousOpticalNETwork)", "sourcePage": 147, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-3-4", "round": 134, "session": 3, "number": 4, "text": "데이터베이스 무결성 제약 조건에 대하여 다음을 설명하시오 . 가 .데이터베이스 무결성 제약 조건의 개념 나 .데이터베이스 무결성 제약 조건의 종류 다 .데이터베이스 무결성 제약 조건 생성 시 고려사항", "sourcePage": 148, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-3-5", "round": 134, "session": 3, "number": 5, "text": "네트워크 프로토콜에 대하여 다음을 설명하시오 . 가 .프로토콜의 개념 나 .프로토콜의 3가지 요소 다 .프로토콜의 기능", "sourcePage": 148, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-3-6", "round": 134, "session": 3, "number": 6, "text": "웹 방화벽 ,침입탐지시스템 (IDS: IntrusionDetectionSystem)및 침입방지시스템 (IPS:IntrusionPreventionSystem)의 개념과 기능을 설명하시오 .", "sourcePage": 148, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-4-1", "round": 134, "session": 4, "number": 1, "text": "소프트웨어 프로세스 품질인증 제도의 운영과 활성화를 위하여 “소프트웨어 프로세스 (SP: SoftwareProcess)품질인증 운영에 관한 지침 ”을 시행하고 있다 .다음에 대해서 설명하시오 . 가 .소프트웨어 프로세스 품질인증 기준 나 .소프트웨어 프로세스 인증등급 기준", "sourcePage": 149, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-4-2", "round": 134, "session": 4, "number": 2, "text": "자동차에 대한 기능안전 규격인 ISO 26262에 대하여 다음을 설명하시오 . 가 .ISO 26262구성요소 나 .자동차 안전 무결성 수준 (ASIL:AutomotiveSafetyIntegrityLevel)", "sourcePage": 149, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-4-3", "round": 134, "session": 4, "number": 3, "text": "병렬 컴퓨팅에 대하여 다음을 설명하시오 . 가 .병렬 컴퓨팅의 개념 나 .병렬 프로세서의 분류", "sourcePage": 149, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-4-4", "round": 134, "session": 4, "number": 4, "text": "개인정보보호 강화기술 (PET:PrivacyEnhancedTechnology)에대하여 다음을 설명하시오 . 가 .PET의 개념 나 .PET의 주요 유형 다 .PET의 적용 사례", "sourcePage": 150, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-4-5", "round": 134, "session": 4, "number": 5, "text": "HDLC (High-levelDataLinkControl)프로토콜의 다음 사항에 대하여 설명하시오 . 가 .기능 나 .프 레임 구조 다 .동 작 모드", "sourcePage": 150, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "134-4-6", "round": 134, "session": 4, "number": 6, "text": "멀티 모 달 인공지능에 관한 다음 사항을 설명하시오 . 가 .개념 나 .구성요소 다 .핵심 기술", "sourcePage": 150, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-1-1", "round": 135, "session": 1, "number": 1, "text": "지식재산권의 종류", "sourcePage": 151, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-1-2", "round": 135, "session": 1, "number": 2, "text": "SOAP(SimpleObjectAccessProtocol)와REST(RepresentationalStateTransfer)를 비교 설명하시오 .", "sourcePage": 151, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-1-3", "round": 135, "session": 1, "number": 3, "text": "MMU(MemoryManagementUnit)", "sourcePage": 151, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-1-4", "round": 135, "session": 1, "number": 4, "text": "몬테카를로 트리탐색 (MonteCarloTreeSearch)", "sourcePage": 151, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-1-5", "round": 135, "session": 1, "number": 5, "text": "모놀리식 아키텍처 (MonolithicArchitecture)와마이크로서비스아키텍처 (MicroService Architecture)를비교설명하시오 .", "sourcePage": 151, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-1-6", "round": 135, "session": 1, "number": 6, "text": "멀티클라우드 (Multicloud)", "sourcePage": 151, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-1-7", "round": 135, "session": 1, "number": 7, "text": "채널용량 (샤논 제 3정리 ,InformationCapacityTheorem)", "sourcePage": 151, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-1-8", "round": 135, "session": 1, "number": 8, "text": "「 정보시스템 하드웨어 규모산정 지침 (TTAK.KO-10.0292/R3)」에따른 하드웨어 규모산정 방법 3가지", "sourcePage": 151, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-1-9", "round": 135, "session": 1, "number": 9, "text": "인공지능 성능 관련 차원의 저주 (CurseofDimensionality)", "sourcePage": 151, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-1-10", "round": 135, "session": 1, "number": 10, "text": "공공데이터 품질인증", "sourcePage": 151, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-1-11", "round": 135, "session": 1, "number": 11, "text": "운영체제 (OperatingSystem)에서태스크우선순위 상속 (PriorityInheritance)", "sourcePage": 152, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-1-12", "round": 135, "session": 1, "number": 12, "text": "RAG(Retrieval-AugmentedGeneration)", "sourcePage": 152, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-1-13", "round": 135, "session": 1, "number": 13, "text": "EuropeanTelecommunicationsStandardsInstitute(ETSI)의Zero-touchnetwork andServiceManagement(ZSM)", "sourcePage": 152, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-2-1", "round": 135, "session": 2, "number": 1, "text": "「생성형 인공지능 학습을 위한 멀티모달 데이터의 품질검증 방법 (정보통신단체표준 , TTAK.KO-10.1558)」에대하여 아래 사항을 설명하시오 . 가 .생성형 인공지능 학습용 멀티모달 데이터 품질특성 나 .생성 데이터 유형별 유효성 검증 방법", "sourcePage": 153, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-2-2", "round": 135, "session": 2, "number": 2, "text": "인구 구조적 변화와 환경문제 해결책으로 제시되는 지속 가능한 스마트시티 (Smart City)를설명하시오 .", "sourcePage": 153, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-2-3", "round": 135, "session": 2, "number": 3, "text": "정보시스템의 접근통제 정책에는 강제적 접근통제 (MAC,MandatoryAccess Control),임의적 접근통제 (DAC,DiscretionaryAccessControl),역할기반접근통제 (RBAC,Role-BasedAccessControl),속성 기반 접근통제 (ABAC,Attribute-Based AccessControl)가있다 .아래 사항을 설명하시오 . 가 .접근통제 개념 나 .접근통제 정책 비교 다 .MAC +ABAC융합 정책의 필요성 라 .MAC +ABAC융합 정책의 동적 보안 정책 운영 방안", "sourcePage": 153, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-2-4", "round": 135, "session": 2, "number": 4, "text": "캐쉬 메모리 (CacheMemory)에 대하여 아래 사항을 설명하시오 . 가 .캐쉬 메모리 (CacheMemory)교체 기법 나 .WriteThrough와 WriteBack비교 다 .캐쉬 일관성 유지를 위한 MESI프로토콜", "sourcePage": 154, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-2-5", "round": 135, "session": 2, "number": 5, "text": "트래픽 폴리싱 (TrafficPolicing)과트래픽 쉐이핑 (TrafficShaping)에대하여 아래 사항을 설명하시오 . 가 .개념 나 .구성요소 다 .구현 알고리즘 라 .트래픽 폴리싱과 트래픽 쉐이핑 비교", "sourcePage": 154, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-2-6", "round": 135, "session": 2, "number": 6, "text": "데이터베이스 트랜잭션 회복 (Recovery)기법에 대하여 아래 사항을 설명하시오 . 가 .REDO와 UNDO를 이용한 방법 나 .체크포인트 (Checkpoint)를이용한 방법 다 .그림자 페이징 (ShadowPaging)을이용한 방법", "sourcePage": 154, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-3-1", "round": 135, "session": 3, "number": 1, "text": "데이터처리의 효율성과 속도를 높이기 위한 엣지 컴퓨팅 (EdgeComputing)에 대하여 아래 사항을 설명하시오 . 가 .클라우드 환경에서의 엣지 컴퓨팅 나 .엣지 컴퓨팅을 활용한 자율 주행 차량 아키텍처 다 .해양 자율이동체에서의 엣지 컴퓨팅", "sourcePage": 155, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-3-2", "round": 135, "session": 3, "number": 2, "text": "「안티드론 시스템 프레임워크 (정보통신단체표준 ,TTAK.KO-10.1460)」에 대하여 아래 사항을 설명하시오 . 가 .안티드론 시스템 참조구조 나 .기술적 조치 참조구조", "sourcePage": 155, "category": "법규·정책·표준", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-3-3", "round": 135, "session": 3, "number": 3, "text": "과학기술정보통신부는 2024년12월 「 철통 인증 지침 (제로트러스트 가이드라인 )2.0」을 발표하였다 .이와 관련하여 아래 사항을 설명하시오 . 가 .제로트러스트 (ZeroTrust)정의 및 핵심 원칙 나 .제로트러스트 (ZeroTrust)보안 모 델 구성요소 다 .제로트러스트 (ZeroTrust)성숙도 수준 4단계 특징 비교 라 .제로트러스트 (ZeroTrust)도입 절 차", "sourcePage": 155, "category": "시스템보안", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-3-4", "round": 135, "session": 3, "number": 4, "text": "운영체제의 스 케줄링 알고리즘에 대하여 아래 사항을 설명하시오 . 가 .RM(RateMonotonic)스케줄링 나 .MLQ(Multi-LevelQueue)스케줄링 다 .SQMS(SingleQueueMultiprocessorScheduling) 라 .MQMS(MultiQueueMultiprocessorScheduling)", "sourcePage": 156, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-3-5", "round": 135, "session": 3, "number": 5, "text": "블록 체인 (Blockchain)의네트워크 종류와 차이 점에 대하여 설명하시오 .", "sourcePage": 156, "category": "컴퓨터 통신 및 네트워크", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-3-6", "round": 135, "session": 3, "number": 6, "text": "연결 리스트 (LinkedList)에대하여 아래 사항을 설명하시오 . 가 .연결 리스트의 개념 및 적용 분야 나 .연결 리스트 구현 방법 다 .배열 리스트 (ArrayList)와연결 리스트 (LinkedList)의비교", "sourcePage": 156, "category": "컴퓨터 기초이론", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-4-1", "round": 135, "session": 4, "number": 1, "text": "중앙은 행 디지 털 화폐(CBDC,CentralBankDigitalCurrency)설계를위한 고려 사항에 대하여 설명하시오 .", "sourcePage": 157, "category": "미분류", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-4-2", "round": 135, "session": 4, "number": 2, "text": "스마트시티 데이터 거버넌 스 (SmartCityDataGovernance)에대하여 설명하시오 .", "sourcePage": 157, "category": "최신 기술 동향", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-4-3", "round": 135, "session": 4, "number": 3, "text": "서버 이 중화 구성 방안에 대하여 아래 사항을 설명하시오 . 가 .L4스위치 기반 이중화 방안 나 .소프트웨어 기반 이 중화 방안 다 .L4스위치 기반 이중화 방안과 소프트웨어 기반 이 중화 방안 비교", "sourcePage": 157, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-4-4", "round": 135, "session": 4, "number": 4, "text": "소프트웨어의 무중 단 배 포(ZeroDowntimeDeployment)방식에 대하여 설명하시오 .", "sourcePage": 157, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-4-5", "round": 135, "session": 4, "number": 5, "text": "고장허 용 (FaultTolerant)시스템과고가용성 (HighAvailability)시스템에대하여 아래 사항을 설명하시오 . 가 .고 장허 용(FaultTolerant)과고가용성 (HighAvailability)시스템의개념 나 .하드웨어 ,소프트웨어 ,데이터 측면 에서 고 장허 용 (FaultTolerant)기법 다 .고가용성 (HighAvailability)시스템의구성 방법 라 .고 장허 용(FaultTolerant)시스템과 고가용성 (HighAvailability)시스템의비교", "sourcePage": 158, "category": "시스템 SW 및 응용 SW", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}, {"id": "135-4-6", "round": 135, "session": 4, "number": 6, "text": "파이프라인 해저드 (PipelineHazard)에대하여 아래 사항을 설명하시오 . 가 .유형별 발생 원인 나 .해결 방법", "sourcePage": 158, "category": "하드웨어 시스템", "favorite": false, "modelAnswer": "", "myAnswer": "", "memo": ""}];
